import { Book } from "@/lib/types";

export const leviticus: Book = {
  id: "leviticus",
  name: "3. Mose (Levitikus)",
  shortName: "3. Mose",
  testament: "old",
  introduction: `Der heilige Gott will ein heiliges Volk\n**Das dritte Buch Mose** heißt auch Leviticus, weil in ihm die Priestergesetze aufgeschrieben sind und die Priester aus dem Stamm Levi kamen. Die Botschaft, die in den vorgeschriebenen Opfern und Festen liegt, lautet: \"Bring dein Leben mit Gott in Ordnung und bleib in seiner Gegenwart!\" Die Opfer sind dabei keine Leistung, die der Israelit bringen musste, sondern eine Heilsgabe Gottes an Israel, um für entstandene Schuld Sühne zu schaffen. Das Buch handelt von Heiligkeit und Heiligung. Dieser Grundgedanke spiegelt sich mehrfach in den Worten: \"Seid heilig, denn ich bin heilig!\" (11,45; 19,2; 20,7.26)\n****Wie ein Israelit sein Leben mit Gott in Ordnung bringen und mit ihm in Verbindung bleiben kann.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Jahwe rief Mose und sprach dann aus dem Zelt der Gottesbegegnung zu ihm:", heading: "1-16: Der Weg zu dem heiligen Gott\nDie Opfer (1-7)" },
      { number: 2, text: "\"Sag den Israeliten Folgendes: Wenn jemand von euch Jahwe eine Opfergabe bringen möchte, sollt ihr dafür ein Rind, ein Schaf oder eine Ziege nehmen." },
      { number: 3, text: "Wenn er ein Rind als Brandopfer bringen will, muss es ein fehlerfreies männliches Tier sein. Er muss das Tier zum Eingang des Zeltes der Gottesbegegnung bringen, wenn es Jahwe gefallen soll.", heading: "Anweisungen für das Brandopfer" },
      { number: 4, text: "Dann soll er seine Hand auf den Kopf des Brandopfers stützen, damit es wohlgefällig angenommen wird und Sühnung für ihn erwirkt." },
      { number: 5, text: "Anschließend soll er das junge Rind vor Jahwe schlachten. Ein Priester* aus der Nachkommenschaft Aarons soll das Blut des Opfertiers ringsherum an den Altar sprengen, der vor dem Eingang zum Zelt der Gottesbegegnung steht.", footnotes: ["ein Priester. Wörtlich:Die Priester. Die Mehrzahl bedeutet nicht, dass mehrere oder gar alle Priester an der Opferhandlung beteiligt waren. Es soll vielmehr deutlich werden, dass nur Nachkommen Aarons den Priesterdienst tun durften."] },
      { number: 6, text: "Dann soll er dem Brandopfer die Haut abziehen und es in Stücke zerlegen." },
      { number: 7, text: "Die Priester aus der Nachkommenschaft Aarons sollen Feuer auf den Altar tun und Holz darüber schichten." },
      { number: 8, text: "Auf das Holz über dem Feuer sollen sie die Stücke, den Kopf und die Fettteile legen." },
      { number: 9, text: "Die Eingeweide und die Unterschenkel muss der Betreffende vorher mit Wasser gewaschen haben. Der Priester lässt dann alles auf dem Altar verbrennen. So ist es ein Brandopfer, ein Feueropfer, dessen Geruch Jahwe befriedigt." },
      { number: 10, text: "Wenn jemand ein Schaf oder eine Ziege als Brandopfer bringen will, muss es ein männliches Tier ohne Fehler sein." },
      { number: 11, text: "Er soll es an der Nordseite des Altars vor Jahwe schlachten, und ein Priester aus der Nachkommenschaft Aarons soll sein Blut ringsherum an den Altar sprengen." },
      { number: 12, text: "Er soll es in seine Stücke, den Kopf und die Fettteile zerlegen. Der Priester soll sie dann auf das Holz über dem Altarfeuer schichten." },
      { number: 13, text: "Die Eingeweide und die Unterschenkel muss der Betreffende vorher mit Wasser gewaschen haben. Der Priester lässt dann alles auf dem Altar verbrennen. So ist es ein Brandopfer, ein Feueropfer, dessen Geruch Jahwe befriedigt." },
      { number: 14, text: "Wenn jemand vom Geflügel ein Brandopfer bringen will, dann soll es eine Turteltaube oder eine andere junge Taube sein." },
      { number: 15, text: "Der Priester bringe sie zum Altar, kneife ihr den Kopf ab und verbrenne ihn im Altarfeuer. Ihr Blut drücke er an der Wand des Altars aus." },
      { number: 16, text: "Dann soll er den Kropf samt Inhalt abtrennen und ihn neben den Altar Richtung Osten auf den Haufen mit der Fettasche* werfen.", footnotes: ["Fettasche bildete sich aus den verbrannten Holz- und Fettstücken."] },
      { number: 17, text: "Er reiße die Taube an den Flügeln ein, trenne sie aber nicht ab. Dann soll der Priester sie auf dem Holz über dem Altarfeuer verbrennen. So ist es ein Brandopfer, ein Feueropfer, dessen Geruch Jahwe befriedigt." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Wenn jemand Jahwe ein Speisopfer bringen möchte, dann soll es aus Feinmehl bestehen, auf das er Öl gießen und Weihrauch legen muss.", heading: "Anweisungen für das Speisopfer" },
      { number: 2, text: "Er soll es zu den Priestern aus der Nachkommenschaft Aarons bringen. Dann nehme er eine Handvoll von dem mit Öl durchtränkten Mehl und dem Weihrauch und der Priester verbrenne diesen Teil der Gabe auf dem Altar. Es ist ein Feueropfer, dessen Geruch Jahwe befriedigt." },
      { number: 3, text: "Der Rest der Gabe fällt den Priestern aus der Nachkommenschaft Aarons zu. Es ist etwas Höchstheiliges, weil es von den Feueropfern Jahwes stammt." },
      { number: 4, text: "Wenn du ein Ofengebäck als Speisopfer bringen willst, dann soll es aus Feinmehl sein und ohne Sauerteig zubereitet werden, entweder ein Lochbrot* mit Öl angefeuchtet oder ein Fladenbrot, das mit Öl bestrichen ist.", footnotes: ["Lochbrot. Ein runder Brotlaib, der in der Mitte durchstoßen ist und so auf einer Stange aufgehängt werden kann zum Schutz gegen Schimmel und Tierfraß."] },
      { number: 5, text: "Wenn deine Opfergabe auf einer Eisenplatte gebacken wurde, soll sie ohne Sauerteig aus Feinmehl und mit Öl vermengt zubereitet sein." },
      { number: 6, text: "Du sollst sie in Stücke zerbrechen und Öl darauf gießen. Es ist ein Speisopfer." },
      { number: 7, text: "Wenn du etwas in der Pfanne Gebackenes als Speisopfer bringen willst, soll es aus Feinmehl zubereitet und in Öl gebacken sein." },
      { number: 8, text: "Du sollst die so zubereitete Gabe Jahwe bringen und dem Priester überreichen. Der soll es zum Altar tragen." },
      { number: 9, text: "Dann hebe er den zum Verbrennen bestimmten Teil davon ab und lasse ihn auf dem Altar in Rauch aufgehen. So ist es ein Feueropfer, dessen Geruch Jahwe befriedigt." },
      { number: 10, text: "Der Rest der Gabe fällt den Priestern aus der Nachkommenschaft Aarons zu. Es ist etwas Höchstheiliges, weil es von den Feueropfern Jahwes stammt." },
      { number: 11, text: "Kein Speisopfer, das ihr Jahwe bringt, darf mit Sauerteig zubereitet sein. Denn weder vom Sauerteig noch vom Honig darf etwas als Feueropfer in Rauch aufgehen." },
      { number: 12, text: "Nur als Erstlingsgabe dürft ihr sie Jahwe bringen. Auf den Altar aber dürfen sie nicht zum befriedigenden Geruch beitragen." },
      { number: 13, text: "Alle Speisopfer und überhaupt alle Opfergaben müssen gesalzen werden. Denn das Salz ist das Zeichen des Gottesbundes." },
      { number: 14, text: "Wenn du Jahwe eine Gabe von den ersten reifen Früchten bringen willst, dann sollen es frische Körner sein, die geröstet zerstoßen werden." },
      { number: 15, text: "Gieß Öl darüber und leg Weihrauch darauf. Es ist ein Speisopfer." },
      { number: 16, text: "Der Priester verbrennt einen Teil davon samt dem Weihrauch. Es ist ein Feueropfer für Jahwe." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Wenn jemand ein Freudenopfer* bringen möchte und seine Opfergabe für Jahwe aus einem Rind besteht, dann kann er ein männliches oder weibliches Tier bringen. Es muss aber fehlerfrei sein.", heading: "Anweisungen für das Freudenopfer", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 2, text: "Er soll seine Hand auf den Kopf des Opfers stützen und es am Eingang vom Zelt der Gottesbegegnung schlachten. Ein Priester aus der Nachkommenschaft Aarons soll das Blut des Opfertiers ringsherum an den Altar sprengen." },
      { number: 3, text: "Ein Teil des Freudenopfers soll für Jahwe verbrannt werden, und zwar alles Fett an den Eingeweiden," },
      { number: 4, text: "die beiden Nieren mit ihrem Fett und das Fett an den Lenden. Den Lappen über der Leber trenne er mit den Nieren ab." },
      { number: 5, text: "Der Priester aus der Nachkommenschaft Aarons soll es zusammen mit den Brandopfern auf dem Altar in Rauch aufgehen lassen. So ist es ein Feueropfer, dessen Geruch Jahwe befriedigt." },
      { number: 6, text: "Wenn jemand ein Schaf oder eine Ziege als Freudenopfer bringen will, kann es ein männliches oder weibliches Tier sein. Es darf aber keine Fehler haben." },
      { number: 7, text: "Wenn seine Opfergabe ein Schafböckchen ist, soll er es zu Jahwe bringen," },
      { number: 8, text: "seine Hand auf den Kopf des Opfers stützen und es vor dem Zelt der Gottesbegegnung schlachten. Einer von den Nachkommen Aarons soll sein Blut ringsherum an den Altar sprengen." },
      { number: 9, text: "Das Fett des Freudenopfers soll als Feueropfer für Jahwe verbrannt werden: der Fettschwanz* – er soll dicht beim Schwanzwirbel abgetrennt werden – und alles Fett, das an den Eingeweiden ist,", footnotes: ["Fettschwanz. Im Orient gab es Schafe mit schwerem Fettschwanz, der mehr als fünf Kilogramm wiegen konnte und als besondere Delikatesse galt."] },
      { number: 10, text: "dazu die beiden Nieren mit ihrem Fett und das Fett an den Lenden. Den Lappen über der Leber trenne er mit den Nieren ab." },
      { number: 11, text: "Der Priester soll es auf dem Altar in Rauch aufgehen lassen. So ist es eine Speise für das Feueropfer Jahwes." },
      { number: 12, text: "Wenn seine Opfergabe eine Ziege ist, soll er sie zu Jahwe bringen," },
      { number: 13, text: "seine Hand auf ihren Kopf stützen und sie vor dem Zelt der Gottesbegegnung schlachten. Einer von den Nachkommen Aarons soll ihr Blut ringsherum an den Altar sprengen." },
      { number: 14, text: "Das Fett des Freudenopfers soll als Feueropfer für Jahwe verbrannt werden: alles Fett, das an den Eingeweiden ist," },
      { number: 15, text: "dazu die beiden Nieren mit ihrem Fett und das Fett an den Lenden. Den Lappen über der Leber trenne er mit den Nieren ab." },
      { number: 16, text: "Der Priester soll es auf dem Altar in Rauch aufgehen lassen. So ist es eine Speise für das Feueropfer, ein Geruch der Befriedigung.Alles Fett gehört Jahwe." },
      { number: 17, text: "Das soll eine ewige Ordnung bei allen euren Nachkommen sein, überall, wo sie wohnen: Keiner von euch darf irgendwelches Fett* oder Blut essen!\"", footnotes: ["Fett. Gemeint ist das Hartfett, das lose aufliegt und sich leicht ablösen lässt."] },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Das Sündopfer für unabsichtliche Sünden ..." },
      { number: 2, text: "\"Gib den Israeliten weiter: Wenn jemand unabsichtlich etwas tut, was Jahwe verboten hat, und gegen irgendein Gebot Jahwes verstößt, gilt Folgendes:" },
      { number: 3, text: "Wenn der gesalbte Priester sich verfehlt und dadurch Schuld über das ganze Volk bringt, dann muss er für seine begangene Sünde Jahwe einen fehlerfreien Jungstier als Sündopfer bringen.", heading: "... eines Priesters" },
      { number: 4, text: "Er muss den Stier an den Eingang vom Zelt der Gottesbegegnung zu Jahwe bringen, seine Hand auf dessen Kopf stützen und den Stier vor Jahwe schlachten." },
      { number: 5, text: "Dann bringe er einen Teil des Blutes ins Zelt der Gottesbegegnung." },
      { number: 6, text: "Er tauche seinen Finger in das Blut und sprenge siebenmal etwas davon in Richtung des Vorhangs*.", footnotes: ["Es ist der Vorhang vor dem Höchstheiligen, so auch Vers 17."] },
      { number: 7, text: "Dann streiche er etwas von dem Blut an die Hörner* des Altars, der im Zelt der Gottesbegegnung vor Jahwe steht und auf dem wohlriechender Weihrauch verbrannt wird. Den Rest des Blutes schütte er an den Fuß des Brandopferaltars, der vor dem Zelt der Gottesbegegnung steht.", footnotes: ["Die Hörner waren Vorsprünge an den vier Ecken des Altars."] },
      { number: 8, text: "Dann soll er das ganze Fett vom Stier des Sündopfers abheben: das gesamte Fett an den Eingeweiden," },
      { number: 9, text: "dazu die beiden Nieren mit ihrem Fett und das Fett an den Lenden. Den Lappen über der Leber trenne er mit den Nieren ab." },
      { number: 10, text: "Er soll es genauso abheben, wie es beim Stier des Freudenopfers gemacht wird. Dann soll der Priester es auf dem Brandopferaltar in Rauch aufgehen lassen." },
      { number: 11, text: "Aber die Haut des Stiers und sein ganzes Fleisch, auch seinen Kopf, die Unterschenkel, die Eingeweide und den Mageninhalt," },
      { number: 12, text: "also den ganzen übrigen Stier, soll er aus dem Lager hinausbringen an den abgesonderten Ort, wo man die Fettasche hinschüttet. Dort, auf dem Schutthaufen der Fettasche, soll er den Stier auf Holzscheiten verbrennen." },
      { number: 13, text: "Wenn die ganze Gemeinschaft Israels unabsichtlich sündigt und die Sache der Versammlung verborgen geblieben ist, dass sie irgendetwas von dem tut, was Jahwe verboten hat, und dadurch schuldig wird,", heading: "... der Gemeinschaft" },
      { number: 14, text: "dann muss sie, sobald die Sünde erkannt wird, einen jungen Stier als Sündopfer vor das Zelt der Gottesbegegnung bringen." },
      { number: 15, text: "Die Ältesten der Gemeinschaft sollen vor Jahwe ihre Hände auf den Kopf des Stiers stützen und den Stier dann vor Jahwe schlachten." },
      { number: 16, text: "Der gesalbte Priester bringe dann etwas von dem Blut des Stiers ins Zelt der Gottesbegegnung." },
      { number: 17, text: "Er tauche seinen Finger in das Blut und sprenge siebenmal etwas davon in Richtung des Vorhangs." },
      { number: 18, text: "Dann streiche er etwas von dem Blut an die Hörner des Altars, der vor Jahwe, also im Zelt der Gottesbegegnung, steht. Den Rest des Blutes schütte er am Fuß des Brandopferaltars aus, der vor dem Zelt steht." },
      { number: 19, text: "All sein Fett soll er von ihm abheben und auf dem Altar in Rauch aufgehen lassen." },
      { number: 20, text: "Er soll mit dem jungen Stier genauso verfahren wie mit dem Stier des Sündopfers. So erwirke der Priester Sühnung für die Gemeinschaft und es wird ihr vergeben werden." },
      { number: 21, text: "Dann soll man den Stier nach draußen vor das Lager bringen und ihn verbrennen, wie man es mit dem ersten Stier getan hat. Es ist ein Sündopfer der Versammlung." },
      { number: 22, text: "Wenn einer der Oberen sündigt und unabsichtlich irgendetwas von dem tut, was Jahwe, sein Gott, verboten hat, wird er schuldig.", heading: "... eines Oberen" },
      { number: 23, text: "Sobald ihm seine Schuld bewusst wird, muss der Betreffende einen fehlerfreien Ziegenbock als Opfergabe bringen." },
      { number: 24, text: "Er soll seine Hand auf den Kopf des Ziegenbocks stützen und ihn am Platz des Brandopfers vor Jahwe schlachten. Es ist ein Sündopfer." },
      { number: 25, text: "Der Priester streiche dann mit dem Finger etwas von dem Blut an die Hörner des Brandopferaltars und gieße den Rest an dessen Fuß aus." },
      { number: 26, text: "Das ganze Fett aber soll er auf dem Altar in Rauch aufgehen lassen so wie das Fett des Freudenopfers. Auf diese Weise erwirke der Priester ihm Sühne für seine Sünde, und es wird ihm vergeben werden." },
      { number: 27, text: "Wenn irgendjemand aus dem Volk unabsichtlich sündigt, indem er etwas von dem tut, was Jahwe verboten hat, wird er schuldig.", heading: "... eines einzelnen Israeliten" },
      { number: 28, text: "Sobald ihm seine Schuld bewusst wird, soll er eine fehlerfreie Ziege als Opfergabe für seine Sünde bringen, ein weibliches Tier." },
      { number: 29, text: "Er soll seine Hand fest auf den Kopf des Sündopfers legen und es dort schlachten, wo man das Brandopfer schlachtet." },
      { number: 30, text: "Der Priester streiche dann mit dem Finger etwas von dem Blut an die Hörner des Brandopferaltars und gieße den Rest am Fuß des Altars aus." },
      { number: 31, text: "Alles Fett soll er abtrennen, wie das auch beim Freudenopfer geschieht. Der Priester lasse es auf dem Altar in Rauch aufgehen als einen Geruch, der Jahwe befriedigt. So erwirke der Priester ihm Sühne, und es wird ihm vergeben werden." },
      { number: 32, text: "Wenn er ein Schaf als Sündopfer bringen will, dann soll es ein fehlerloses weibliches Tier sein." },
      { number: 33, text: "Er soll seine Hand fest auf den Kopf des Sündopfers legen und es am Platz des Brandopfers schlachten." },
      { number: 34, text: "Der Priester streiche dann mit dem Finger etwas von dem Blut an die Hörner des Brandopferaltars und gieße den Rest an dessen Fuß aus." },
      { number: 35, text: "Alles Fett soll er abtrennen, wie das auch beim Freudenopfer geschieht. Der Priester lasse es auf dem Altar, auf dem Feuer Jahwes, in Rauch aufgehen. So erwirke der Priester ihm Sühne für die Sünde, die er begangen hat, und es wird ihm vergeben werden." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Wenn jemand dadurch sündigt, dass er den Bannfluch* am Beginn eines Prozesses zwar hört, aber als Zeuge der Sache dennoch keine Aussage macht, lädt er Schuld auf sich.", heading: "Gesetze vom Sünd- und Schuldopfer", footnotes: ["Bannfluch. Ein Prozess in Israel wurde durch Zeugen entschieden. Deshalb wurden am Beginn des Prozesses alle Zeugen unter den Anwesenden aufgerufen, auch tatsächlich auszusagen (und nicht aus Sympathie mit dem Angeklagten zu schweigen), denn sonst würden sie sich vor Gott schuldig machen."] },
      { number: 2, text: "Wenn jemand etwas Unreines berührt, zum Beispiel das Aas irgendeines Tieres, wird er schuldig, sobald er es erkennt." },
      { number: 3, text: "Oder wenn jemand mit der Unreinheit eines Menschen in Berührung kommt – egal, wodurch sie verursacht wurde, – wird er schuldig, sobald er es erkennt." },
      { number: 4, text: "Oder wenn jemand unbedacht schwört, ohne es wahrzunehmen, egal ob zum Schaden oder zum Nutzen, so wie ein Schwur eben unbedacht über die Lippen kommen kann, auch durch so etwas wird er schuldig, sobald er es erkennt." },
      { number: 5, text: "Wenn also jemand in einem dieser Fälle schuldig wird, soll er bekennen, wodurch er gesündigt hat." },
      { number: 6, text: "Er muss Jahwe ein Schuldopfer für die begangene Sünde bringen, ein weibliches Tier vom Kleinvieh, ein Schaf oder eine Ziege. So soll der Priester Sühne für ihn erwirken." },
      { number: 7, text: "Wenn seine Mittel für ein Lamm nicht ausreichen, soll er Jahwe als Schuldopfer für seine Verfehlung zwei Turteltauben oder zwei junge Tauben bringen, eine zum Sündopfer und eine zum Brandopfer." },
      { number: 8, text: "Der Priester nehme zuerst die zum Sündopfer bestimmte und kneife ihr den Kopf am Genick ab. Er soll ihn aber nicht völlig abtrennen." },
      { number: 9, text: "Dann sprenge er etwas vom Blut des Sündopfers an die Wand des Altars. Das übrige Blut drücke er am Fuß des Altars aus. Es ist ein Sündopfer." },
      { number: 10, text: "Die zweite Taube soll er als Brandopfer nach Vorschrift darbringen. So erwirke der Priester ihm Sühne für die Sünde, die er begangen hat, und es wird ihm vergeben werden." },
      { number: 11, text: "Wenn seine Mittel für zwei Turteltauben oder Jungtauben nicht ausreichen, dann bringe er als Sündopfer zwei Liter* Feinmehl. Er soll aber kein Öl darauf gießen und keinen Weihrauch darauf legen, denn es ist ein Sündopfer.", footnotes: ["zwei Liter. Wörtlich: ein Zehntel Efa. Efa ist ein Hohlmaß von 22 Litern."] },
      { number: 12, text: "Der Priester nimmt eine Handvoll davon und lässt diesen Teil auf dem Altar, auf dem Feuer Jahwes, in Rauch aufgehen. Es ist ein Sündopfer." },
      { number: 13, text: "So erwirke der Priester ihm Sühne für die Sünde, die er in einem der Fälle begangen hat, und es wird ihm vergeben werden. Das übrige Mehl gehört dem Priester wie beim Speisopfer.\"" },
      { number: 14, text: "Jahwe sagte zu Mose:", heading: "Das Schuldopfer" },
      { number: 15, text: "\"Wenn jemand ohne Absicht etwas veruntreut und sich so an den heiligen Gaben für Jahwe versündigt, dann soll er Jahwe sein Schuldopfer bringen: einen fehlerfreien Schaf- oder Ziegenbock im Wert von einigen Silberstücken nach dem Gewicht des Heiligtums." },
      { number: 16, text: "Und die Gaben, die der Betreffende schuldig geblieben ist, muss er dem Priester erstatten und noch ein Fünftel dazugeben. Mit dem Bock soll der Priester ihm Sühne erwirken, dann wird ihm vergeben werden." },
      { number: 17, text: "Wenn jemand sich verfehlt und etwas tut, was Jahwe verboten hat, hat er damit Schuld auf sich geladen, auch, wenn er es nicht erkannte." },
      { number: 18, text: "Der Betreffende soll dem Priester einen fehlerlosen Schaf- oder Ziegenbock im üblichen Wert als Schuldopfer bringen. Der Priester soll ihm Sühne für das Vergehen erwirken, das er, ohne es zu erkennen, begangen hat. Dann wird ihm vergeben werden." },
      { number: 19, text: "Es handelt sich um ein Schuldopfer. Er ist auf jeden Fall an Jahwe schuldig geworden.\"" },
      { number: 20, text: "Jahwe sagte zu Mose:" },
      { number: 21, text: "\"Wenn jemand sündigt und Jahwe untreu wird, indem er etwas, das sein Nächster ihm zur Aufbewahrung anvertraut hat, ableugnet oder ein Darlehen, das dieser ihm gab, nicht zurückzahlt, oder etwas von ihm raubte oder erpresste," },
      { number: 22, text: "oder wenn er etwas Verlorenes gefunden hat und das ableugnet, oder wenn er falsch schwört oder wenn er sonst etwas tut und sich versündigt," },
      { number: 23, text: "dann ist er schuldig geworden. Er muss das Geraubte oder Erpresste, das ihm Anvertraute oder das Gefundene zurückerstatten," },
      { number: 24, text: "auch alles, was er durch falschen Eid bekam. Er muss es erstatten und noch ein Fünftel hinzufügen. Am Tag seines Schuldopfers soll er es zurückgeben." },
      { number: 25, text: "Und sein Schuldopfer soll er Jahwe bringen, indem er dem Priester einen fehlerfreien Schaf- oder Ziegenbock übergibt." },
      { number: 26, text: "Der Priester soll ihm vor Jahwe Sühne erwirken, dann wird ihm alles vergeben werden, wodurch er schuldig geworden ist.\"" },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Opfervorschriften für die Priester ..." },
      { number: 2, text: "\"Gib Aaron und seinen Söhnen folgende Weisungen weiter:Für das Brandopfer gilt folgende Anordnung: Es muss die ganze Nacht über auf dem Altarfeuer bleiben und das Feuer muss bis zum Morgen in Brand gehalten werden." },
      { number: 3, text: "Dann soll der Priester das Gewand aus Leinen und die leinene Kniehose anziehen. Anschließend nehme er die Fettasche des Brandopfers vom Feuer und schütte sie neben den Altar.", heading: "... für das Brandopfer" },
      { number: 4, text: "Dann wechsle er seine Kleidung und trage die Fettasche hinaus vor das Lager an einen abgesonderten Ort." },
      { number: 5, text: "Das Feuer auf dem Altar muss immer in Brand gehalten werden, es darf nicht erlöschen. Der Priester soll jeden Morgen Holz anzünden und die Fettstücke der Freudenopfer auf ihm in Rauch aufgehen lassen." },
      { number: 6, text: "Auf dem Altar muss ein beständiges Feuer in Brand gehalten werden. Es darf nicht erlöschen." },
      { number: 7, text: "Für das Speisopfer gilt folgende Anordnung: Die Nachkommen Aarons müssen es Jahwe auf dem Altar darbringen.", heading: "... für das Speisopfer" },
      { number: 8, text: "Der Priester nehme eine Handvoll von dem mit Öl durchtränkten Feinmehl, auf dem sich der Weihrauch befindet, und lasse es auf dem Altar in Rauch aufgehen. Der Geruch von diesem, zum Verbrennen bestimmten Teil, befriedigt Jahwe." },
      { number: 9, text: "Den Rest davon müssen die Priester essen. Es muss aber ohne Sauerteig zubereitet und an heiliger Stätte, im Vorhof zum Heiligtum, gegessen werden." },
      { number: 10, text: "Es darf nicht mit Sauerteig verbacken werden, denn es ist ihr Anteil von meinen Feueropfern, es ist höchst heilig wie das Sünd- und das Schuldopfer." },
      { number: 11, text: "Nur die männlichen Nachkommen Aarons dürfen davon essen. Das gilt für jede Generation. Es ist ihr immerwährendes Anrecht an den Feueropfern Jahwes. Alles, was mit ihnen in Berührung kommt, wird heilig.\"" },
      { number: 12, text: "Jahwe sagte zu Mose:", heading: "... für das Opfer bei der Priesterweihe" },
      { number: 13, text: "\"Folgende Opfergabe sollen Aaron und seine Nachkommen Jahwe bringen, und zwar vom Tag ihrer Salbung an: zwei Liter Feinmehl als regelmäßiges Speisopfer, die eine Hälfte am Morgen, die andere am Abend." },
      { number: 14, text: "Es soll in einer Pfanne mit Öl eingerührt und zu einem Fladen verbacken werden. Dieser Fladen soll dann in Stücke zerbrochen und so Jahwe gebracht werden, damit daraus ein Geruch entsteht, der ihn befriedigt." },
      { number: 15, text: "Der Priester, der an Aarons Stelle zum Hohen Priester gesalbt wird, soll es opfern. Das ist eine immerwährende Ordnung: Es soll für Jahwe ganz in Rauch aufgehen." },
      { number: 16, text: "Jedes Speisopfer eines Priesters ist ein Ganzopfer. Es darf nicht gegessen werden.\"" },
      { number: 17, text: "Jahwe sagte zu Mose:", heading: "... für das Sündopfer" },
      { number: 18, text: "\"Gib Aaron und seinen Söhnen folgende Anweisung für das Sündopfer weiter: Dort, wo das Brandopfer geschlachtet wird, muss auch das Sündopfer vor Jahwe geschlachtet werden. Es ist höchst heilig." },
      { number: 19, text: "Der Priester, der das Tier als Sündopfer darbringt, darf es essen. Es muss allerdings an heiliger Stätte gegessen werden, im Vorhof vom Zelt der Gottesbegegnung." },
      { number: 20, text: "Alles, was mit dem Fleisch in Berührung kommt, wird geheiligt sein. Wenn ein Spritzer von seinem Blut auf ein Kleidungsstück kommt, muss der Fleck an heiliger Stätte ausgewaschen werden." },
      { number: 21, text: "Wenn es in einem Tongefäß gekocht wird, muss dieses anschließend zerbrochen werden, ein Metallgefäß muss anschließend gescheuert und mit Wasser gespült werden." },
      { number: 22, text: "Nur die männlichen Mitglieder der Priesterfamilien dürfen davon essen. Es ist höchst heilig." },
      { number: 23, text: "Aber jedes Sündopfer, von dessen Blut etwas ins Zelt der Gottesbegegnung gebracht wird, um dort im Heiligtum Sühne zu bewirken, darf man nicht essen. Es muss verbrannt werden." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Folgende Anordnung gilt für das Schuldopfer: Es ist höchst heilig.", heading: "... für das Schuldopfer" },
      { number: 2, text: "Dort, wo das Brandopfer geschlachtet wird, muss auch das Schuldopfer geschlachtet werden. Der Priester soll das Blut des Opfertiers ringsherum an den Altar sprengen." },
      { number: 3, text: "Alles Fett davon muss er opfern: das Fett an den Eingeweiden," },
      { number: 4, text: "die beiden Nieren mit ihrem Fett und das Fett an den Lenden. Den Lappen über der Leber trenne er mit den Nieren ab." },
      { number: 5, text: "Der Priester soll es auf dem Altar als ein Feueropfer für Jahwe in Rauch aufgehen lassen. Es ist ein Schuldopfer." },
      { number: 6, text: "Nur die männlichen Mitglieder der Priesterfamilien dürfen davon essen. Und es darf nur an heiliger Stätte gegessen werden, denn es ist höchst heilig." },
      { number: 7, text: "Für das Schuldopfer gilt dieselbe Ordnung wie für das Sündopfer. Es gehört dem Priester, der damit Sühnung erwirkt." },
      { number: 8, text: "Dem Priester, der ein Brandopfer für jemand darbringt, gehört die Haut des Opfers." },
      { number: 9, text: "Auch jedes Speisopfer, das im Ofen gebacken oder in der Pfanne oder auf einer Eisenplatte zubereitet wird, gehört dem Priester, der es darbringt." },
      { number: 10, text: "Alle übrigen Speisopfer, die mit Öl vermengt oder trocken sind, sollen unter allen Priestern aus der Nachkommenschaft Aarons aufgeteilt werden." },
      { number: 11, text: "Für das Freudenopfer, das man Jahwe bringt, gilt folgende Anordnung:", heading: "... für das Freudenopfer" },
      { number: 12, text: "Wird es als Dankopfer gebracht, sollen außerdem noch mit Öl angefeuchtete Lochbrote und mit Öl bestrichene Brotfladen gebracht werden, beides ohne Sauerteig zubereitet. Dazu kommt Lochbrot aus Feinmehl, das mit Öl vermengt worden ist." },
      { number: 13, text: "Außer dem Lochbrot soll man auch gesäuertes Brot als Gabe zu dem Friedens-Dankopfer bringen." },
      { number: 14, text: "Von jeder Art Brot hebe der Opfernde ein Stück für Jahwe ab und übergebe es dem Priester, der das Blut des Freudenopfers versprengt. Ihm soll es gehören." },
      { number: 15, text: "Das Fleisch des Friedens-Dankopfers soll an dem Tag gegessen werden, an dem das Opfer gebracht wird. Es darf nichts davon bis zum nächsten Morgen liegengelassen werden." },
      { number: 16, text: "Wenn es sich um ein Gelübde oder ein freiwilliges Opfer handelt, soll das Fleisch des Schlachtopfers ebenfalls an dem Tag gegessen werden, an dem es gebracht wurde. Hiervon darf man allerdings auch am nächsten Tag noch essen, was übriggeblieben ist." },
      { number: 17, text: "Wenn am dritten Tag immer noch etwas davon übrig ist, muss es verbrannt werden." },
      { number: 18, text: "Wenn vom Fleisch des Freudenopfers am dritten Tag noch etwas gegessen wird, wird der, der es darbringt, kein Wohlgefallen finden. Es wird ihm nicht angerechnet werden. Es gilt als unrein. Und wer davon isst, wird sich Schuld aufladen." },
      { number: 19, text: "Fleisch, das mit irgendetwas Unreinem in Berührung kommt, darf nicht gegessen, sondern muss verbrannt werden. Alles andere Fleisch aber darf von jedem gegessen werden, der rein ist." },
      { number: 20, text: "Wenn aber eine Person im Zustand der Unreinheit vom Fleisch des Freudenopfers isst, das Jahwe geweiht wurde, muss diese Person vom Volk beseitigt werden." },
      { number: 21, text: "Wenn eine Person etwas Unreines berührt, sei es die Unreinheit an einem Menschen, einem Stück Vieh oder eine unreine Abscheulichkeit, und isst vom Fleisch des Freudenopfers, das Jahwe geweiht wurde, muss diese Person vom Volk beseitigt werden.\"" },
      { number: 22, text: "Jahwe sagte zu Mose:", heading: "Das Verbot von Fett- und Blutgenuss" },
      { number: 23, text: "\"Gib den Israeliten Folgendes weiter: Ihr dürft keinerlei Fett essen, weder vom Stier noch vom Schaf noch von der Ziege." },
      { number: 24, text: "Das Fett von verendeten oder zerrissenen Tieren dürft ihr für irgendwelche Zwecke verwenden, aber ihr dürft es auf keinen Fall essen." },
      { number: 25, text: "Jeder, der dennoch vom Fett eines Tieres isst, das Jahwe als Opfer gebracht werden kann: Diese Person muss vom Volk beseitigt werden." },
      { number: 26, text: "Ihr dürft auch kein Blut verzehren, weder von Vögeln noch vom Vieh, wo immer ihr auch wohnt." },
      { number: 27, text: "Jede Person, die irgendwelches Blut isst, muss vom Volk beseitigt werden.\"" },
      { number: 28, text: "Jahwe sagte zu Mose:", heading: "Der Priesteranteil am Opfer" },
      { number: 29, text: "\"Gib den Israeliten Folgendes weiter: Wer Jahwe ein Freudenopfer bringt, soll folgende Opfergaben davon für Jahwe herbeibringen:" },
      { number: 30, text: "Mit seinen Händen bringe er das, was zum Feueropfer gehört: das Fett zusammen mit der Brust. Die Brust soll er hin- und herschwingend Jahwe darbieten." },
      { number: 31, text: "Das Fett soll der Priester auf dem Altar in Rauch aufgehen lassen, die Brust aber soll den Priestern gehören." },
      { number: 32, text: "Auch die rechte Hinterkeule sollt ihr von euren Freudenopfern abheben und dem Priester geben." },
      { number: 33, text: "Wer von den Nachkommen Aarons das Blut und das Fett des Freudenopfers darbringt, dem steht auch die rechte Hinterkeule zu." },
      { number: 34, text: "Denn die Brust der Schwinggabe und die Gabe der rechten Hinterkeule nehme ich von ihren Freudenopfern und gebe sie den Priestern aus der Nachkommenschaft Aarons. Diese Anordnung gilt für alle in Israel und für immer." },
      { number: 35, text: "Das also ist der Anteil, der Aaron und seinen Nachkommen von den Feueropfern Jahwes zusteht, und zwar von dem Tag an, an dem sie zum Priesterdienst gesalbt wurden." },
      { number: 36, text: "Aufgrund der Anordnung Jahwes sind die Israeliten verpflichtet, den Priestern diesen Anteil zu geben. Das ist eine immerwährende Ordnung von Generation zu Generation.\"" },
      { number: 37, text: "Das sind die Anordnungen für das Brandopfer, das Speisopfer und das Sündopfer, für das Schuldopfer, das Einweihungsopfer und das Freudenopfer." },
      { number: 38, text: "Jahwe gab diese Anweisungen Mose auf dem Berg Sinai an dem Tag, als er den Israeliten in der Wüste Sinai befahl, ihm Opfer zu bringen." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Priester (8-10)\nDie Priesterweihe" },
      { number: 2, text: "\"Nimm Aaron und seine Söhne mit dir, dazu die Priesterkleider, das Salböl, den Stier für das Sündopfer, die beiden Schafböcke und den Korb mit den ungesäuerten Broten" },
      { number: 3, text: "und lass die ganze Gemeinschaft Israels zum Eingang vom Zelt der Gottesbegegnung kommen!\"" },
      { number: 4, text: "Mose machte es so, wie Jahwe es ihm befohlen hatte, und die Gemeinschaft versammelte sich am Eingang vom Zelt der Gottesbegegnung." },
      { number: 5, text: "Dann sagte Mose zu ihnen: \"Was ihr mich jetzt tun seht, hat Jahwe befohlen.\"" },
      { number: 6, text: "Mose ließ Aaron und seine Söhne herantreten und begoss sie mit Wasser." },
      { number: 7, text: "Dann zog er Aaron das Priesterhemd an und band ihm den Gürtel um. Er legte ihm das Obergewand an, darüber das Efod* und band es mit dem dazugehörenden Gürtel fest.", footnotes: ["Efod. Ein sehr kostbares ärmelloses Gewand, das der Hohepriester über dem Obergewand trug (2. Mose 39). Am Efod waren die mit Edelsteinen besetzten Schulterstücke und das Brustschild befestigt."] },
      { number: 8, text: "Dann hängte er ihm die Brusttasche um, welche die Urim und Tummim* enthielt.", footnotes: ["Urim und Tummim waren die heiligen Lose, die bei schwierigen Entscheidungen den Schiedsspruch herbeiführten. Die Bedeutung der hebräischen Begriffe ist unsicher. Nach der griechischen Übersetzung des Alten Testaments, die im 3. Jahrhundert v.Chr. in Alexandria entstand, der sogenannten Septuaginta (=LXX), bedeuteten sie Licht und Recht."] },
      { number: 9, text: "Er band ihm den Kopfbund um und befestigte daran das heilige Diadem, das Stirnblatt aus Gold, so wie Jahwe es ihm befohlen hatte." },
      { number: 10, text: "Danach salbte Mose mit dem Öl die Wohnstätte und alles, was darin war, und weihte sie damit." },
      { number: 11, text: "Sieben Mal sprengte er von dem Öl auf den Altar und salbte ihn so, um ihn zu weihen, ebenfalls alle dazugehörenden Geräte, auch das Becken und sein Gestell." },
      { number: 12, text: "Dann goss er etwas von dem Öl über den Kopf Aarons und salbte ihn auf diese Weise, um ihn zum Priester zu weihen." },
      { number: 13, text: "Anschließend ließ Mose die Söhne Aarons herantreten, bekleidete sie mit Priesterhemd, Gürtel und Kopfbund, wie Jahwe es ihm befohlen hatte." },
      { number: 14, text: "Dann ließ er den jungen Stier für das Sündopfer herbeiführen, und Aaron und seine Söhne stützten ihre Hände auf den Kopf des Sündopferstiers." },
      { number: 15, text: "Dann schlachtete Mose den Stier, nahm Blut von ihm und strich es mit dem Finger an die Hörner des Altars. Auf diese Weise entsündigte er den Altar. Den Rest des Blutes schüttete er am Fuß des Altars aus. Auf diese Weise erwirkte er Sühne für ihn und heiligte ihn." },
      { number: 16, text: "Dann nahm er das ganze Fett, das an den Eingeweiden ist, den Lappen an der Leber und die beiden Nieren mit ihrem Fett und ließ sie auf dem Altar in Rauch aufgehen." },
      { number: 17, text: "Den Rest des jungen Stiers, seine Haut, sein Fleisch und seine Eingeweide, verbrannte er draußen vor dem Lager, wie Jahwe es ihm befohlen hatte." },
      { number: 18, text: "Dann ließ er den Schafbock für das Brandopfer herbeibringen. Aaron und seine Söhne stützten ihre Hände auf dessen Kopf." },
      { number: 19, text: "Anschließend schlachtete Mose den Bock und sprengte sein Blut ringsum an den Altar." },
      { number: 20, text: "Er zerlegte das Tier und ließ den Kopf, die Rumpfstücke und das Fett in Rauch aufgehen." },
      { number: 21, text: "Die Eingeweide und Unterschenkel spülte er im Wasser ab und verbrannte auch sie auf dem Altar. So war es ein Brandopfer, dessen Geruch Jahwe befriedigte, ein Feueropfer für Jahwe, genauso, wie er es befohlen hatte." },
      { number: 22, text: "Dann ließ er den zweiten Schafbock, den Bock zur Priesterweihe, herbeibringen. Aaron und seine Söhne stützten ihre Hände auf dessen Kopf." },
      { number: 23, text: "Mose schlachtete ihn, nahm etwas von dem Blut und betupfte damit Aarons rechtes Ohrläppchen, seinen rechten Daumen und seine rechte große Zehe." },
      { number: 24, text: "Anschließend ließ er die Söhne Aarons hervortreten und betupfte auch bei ihnen das rechte Ohrläppchen, den rechten Daumen und die rechte große Zehe. Das übrige Blut sprengte Mose ringsum an den Altar." },
      { number: 25, text: "Darauf nahm er die Fettstücke, den Fettschwanz, alles Fett an den Eingeweiden, den Lappen an der Leber, die beiden Nieren samt ihrem Fett und die rechte Hinterkeule." },
      { number: 26, text: "Aus dem Korb mit den ungesäuerten Broten, der vor Jahwe stand, nahm er ein gewöhnliches Lochbrot, eins, das mit Öl bestrichen war, und ein Fladenbrot und legte es auf die Fettstücke und die rechte Hinterkeule." },
      { number: 27, text: "Das alles gab er Aaron und seinen Söhnen in die Hände und ließ es vor Jahwe als Weihgabe hin- und herschwingen." },
      { number: 28, text: "Dann nahm Mose es wieder aus ihren Händen und ließ es auf dem Altar über dem Brandopfer in Rauch aufgehen. Es war ein Einweihungsopfer, dessen Geruch Jahwe befriedigte, ein Feueropfer für Jahwe." },
      { number: 29, text: "Dann nahm Mose das Bruststück und schwang es als Weihgabe vor Jahwe hin und her. Jahwe hatte bestimmt, dass dieser Teil des Einweihungsopfers Mose gehören sollte." },
      { number: 30, text: "Mose nahm etwas von dem Salböl und etwas vom Blut auf dem Altar und sprengte beides auf Aaron und seine Söhne und ihre Gewänder und heiligte sie so." },
      { number: 31, text: "Dann sagte er zu ihnen: \"Kocht das Fleisch am Eingang vom Zelt der Gottesbegegnung und esst es dort, ebenso das Brot, das im Korb für das Einweihungsopfer liegt, denn ich habe es mit diesen Worten angeordnet: 'Aaron und seine Nachkommen sollen davon essen!'" },
      { number: 32, text: "Den Rest vom Fleisch und Brot sollt ihr verbrennen." },
      { number: 33, text: "Sieben Tage lang sollt ihr am Eingang vom Zelt der Gottesbegegnung bleiben. Ihr dürft euch nicht davon entfernen, bis die Tage für das Einweihungsopfer vorbei sind, denn sieben Tage wird man euch die Hände füllen," },
      { number: 34, text: "wie man es heute gemacht hat. So hat Jahwe es befohlen, um euch Sühne zu erwirken." },
      { number: 35, text: "Bleibt also sieben Tage lang, Tag und Nacht, am Eingang vom Zelt der Gottesbegegnung und beachtet die Anweisungen, damit ihr nicht sterben müsst. So hat Jahwe es mir befohlen.\"" },
      { number: 36, text: "Aaron und seine Söhne machten es so, wie Jahwe es durch Mose angeordnet hatte." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Am achten Tag rief Mose Aaron, dessen Söhne und die Ältesten Israels zusammen.", heading: "Der erste Opfergottesdienst" },
      { number: 2, text: "Dann sagte er zu Aaron: \"Nimm dir ein Stierkalb zum Sündopfer und einen Schafbock zum Brandopfer und bringe sie vor Jahwe. Die Tiere müssen ohne Fehler sein." },
      { number: 3, text: "Sag auch den Israeliten: 'Bringt einen Ziegenbock für das Sündopfer, ein Stierkalb und ein Schaf zum Brandopfer. Es müssen fehlerfreie einjährige Tiere sein." },
      { number: 4, text: "Dazu noch einen Stier und einen Schafbock für das Freudenopfer, um sie vor Jahwe zu schlachten, und ein Speisopfer, das mit Öl vermengt wurde. Denn heute wird Jahwe euch erscheinen.'\"" },
      { number: 5, text: "Sie brachten alles vor das Zelt der Gottesbegegnung, wie Mose es angeordnet hatte. Und die ganze Gemeinschaft versammelte sich dort vor Jahwe." },
      { number: 6, text: "Mose sagte: \"Das ist es, was Jahwe euch zu tun befohlen hat. Nun wird euch die Herrlichkeit Jahwes erscheinen.\"" },
      { number: 7, text: "Zu Aaron sagte Mose: \"Tritt an den Altar und bring das Sünd- und das Brandopfer für dich dar. Erwirke Sühne für dich und das Volk! Bring die Opfer für die Schuld des Volkes und erwirke Sühnung für sie, wie Jahwe es befohlen hat!\"" },
      { number: 8, text: "Aaron trat an den Altar und schlachtete das Stierkalb für seine eigene Sünde." },
      { number: 9, text: "Seine Söhne brachten ihm das Blut. Er tauchte seinen Finger hinein und strich etwas davon an die Hörner des Altars. Den Rest goss er am Fuß des Altars aus." },
      { number: 10, text: "Die Fettstücke, die Nieren und den Lappen an der Leber ließ er auf dem Altar in Rauch aufgehen, so wie Jahwe es Mose befohlen hatte." },
      { number: 11, text: "Das Fleisch und die Haut verbrannte er draußen vor dem Lager." },
      { number: 12, text: "Dann schlachtete er das Brandopfer. Seine Söhne brachten ihm das Blut, und er sprengte es ringsherum an den Altar." },
      { number: 13, text: "Dann reichten sie ihm die Stücke des Opfertiers und den Kopf, und er ließ alles auf dem Altar in Rauch aufgehen." },
      { number: 14, text: "Die Eingeweide und die Unterschenkel wusch er im Wasser und verbrannte sie ebenfalls auf dem Altar." },
      { number: 15, text: "Dann ließ er die Opfergabe des Volkes herbringen. Er schlachtete den Ziegenbock als Opfer für die Sünden des Volkes so, wie er das Sündopfer für sich geschlachtet hatte." },
      { number: 16, text: "Auch das Brandopfer brachte er nach der Vorschrift dar." },
      { number: 17, text: "Vom Speisopfer nahm er eine Handvoll und ließ es auf dem Altar in Rauch aufgehen, zusätzlich zu dem Morgen-Brandopfer." },
      { number: 18, text: "Anschließend schlachtete er den Stier und den Schafbock als Freudenopfer für das Volk. Seine Söhne brachten ihm das Blut, und er sprengte es ringsherum an den Altar." },
      { number: 19, text: "Sie brachten ihm auch die Fettstücke von beiden Tieren, den Fettschwanz, das Fett, das die Eingeweide bedeckt, die Nieren mit ihrem Fett und den Lappen an der Leber" },
      { number: 20, text: "und legten es auf die Bruststücke, damit Aaron sie auf dem Altar in Rauch aufgehen lassen würde." },
      { number: 21, text: "Die Bruststücke und die rechte Hinterkeule schwang Aaron als Weihgabe vor Jahwe hin und her, wie Mose es angeordnet hatte." },
      { number: 22, text: "Nachdem Aaron das Sünd-, das Brand- und das Freudenopfer dargebracht hatte, erhob er seine Hände und segnete alles Volk. Dann stieg er herab." },
      { number: 23, text: "Mose und Aaron gingen anschließend in das Zelt der Gottesbegegnung hinein. Als sie wieder herauskamen, segneten sie das Volk. Da zeigte sich die Herrlichkeit Jahwes dem ganzen Volk." },
      { number: 24, text: "Flammen gingen von ihm aus und verzehrten das Brandopfer auf dem Altar und die Fettstücke. Bei diesem Anblick brach das Volk in Jubel aus, und alle warfen sich zu Boden." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Zwei Söhne Aarons, es waren Nadab und Abihu, nahmen ihre Räucherpfannen, legten Glut und Räucherwerk darauf und brachten Jahwe ein unerlaubtes Feueropfer, das er ihnen nicht geboten hatte.", heading: "Ein unerlaubtes Opfer" },
      { number: 2, text: "Da ging Feuer von Jahwe aus und verzehrte sie. So starben sie vor Jahwe." },
      { number: 3, text: "Mose sagte zu Aaron: \"Das ist es, was Jahwe meinte, als er sagte:An denen, die mir nahe sind, / erweise ich mich als heilig. / Und vor dem ganzen Volk / will ich verherrlicht sein!\"Aaron schwieg." },
      { number: 4, text: "Mose rief Mischaël und Elizafan, die Söhne von Aarons Onkel Usiël, und sagte zu ihnen: \"Kommt her und schafft die Leichen eurer Verwandten vom Heiligtum weg! Bringt sie aus dem Lager hinaus!\"" },
      { number: 5, text: "Sie gehorchten dem Befehl Moses und schafften die Toten in ihren Priesterhemden aus dem Lager hinaus." },
      { number: 6, text: "Mose sagte zu Aaron und dessen Söhnen Eleasar und Itamar: \"Ihr dürft euer Haupthaar jetzt nicht ungepflegt herunterhängen lassen und eure Kleidung nicht zerreißen,* damit ihr nicht auch sterben müsst und Gott über die ganze Gemeinschaft zornig wird. Lasst eure Brüder, die anderen Israeliten, diesen Brand beweinen, den Jahwe angerichtet hat.", footnotes: ["nicht zerreißen. Das heißt: Ihr dürft die herkömmlichen Trauerbräuche nicht anwenden."] },
      { number: 7, text: "Entfernt euch nicht vom Eingang des Zeltes der Gottesbegegnung, damit ihr nicht sterben müsst, denn das Öl der Salbung Jahwes ist auf euch.\" Sie taten, wie Mose es gesagt hatte." },
      { number: 8, text: "Jahwe sagte zu Aaron:", heading: "Besondere Bestimmungen für Priester" },
      { number: 9, text: "\"Wenn ihr ins Zelt der Gottesbegegnung hineingeht, dürft ihr weder Wein noch Bier trinken, sonst müsst ihr sterben. Das ist eine ewige Ordnung für dich und deine Nachkommen." },
      { number: 10, text: "Denn ihr sollt unterscheiden zwischen dem, was heilig, und dem, was nicht heilig ist, zwischen dem, was rein, und dem, was unrein ist." },
      { number: 11, text: "Und ihr sollt die Israeliten unterweisen in all den Ordnungen, die Jahwe euch durch Mose gegeben hat.\"" },
      { number: 12, text: "Mose sagte zu Aaron und seinen überlebenden Söhnen Eleasar und Itamar: \"Was von den Speisopfern übrig bleibt und nicht als Feueropfer für Jahwe verbrannt wird, dürft ihr nehmen und als ungesäuerte Fladen in der Nähe des Altars essen, denn es ist höchst heilig." },
      { number: 13, text: "Ihr müsst es an heiliger Stätte essen, denn es ist der Anteil, der dir und deinen Söhnen von den Feueropfern Jahwes zusteht. So ist es mir geboten worden." },
      { number: 14, text: "Das Bruststück und die Hinterkeule, die dir und deinen Söhnen und Töchtern von den Freudenopfern der Israeliten zustehen, könnt ihr auch an einem anderen reinen Ort verzehren." },
      { number: 15, text: "Die Hinterkeule und die Brust sollt ihr zusammen mit den Fettstücken für das Feueropfer zum Altar bringen und dort vor Jahwe hin- und herschwingen. Danach gehören sie dir und deinen Nachkommen. Das steht euch für alle Zeit als Anteil zu. So hat Jahwe es befohlen.\"" },
      { number: 16, text: "Als Mose nach dem Ziegenbock für das Sündopfer suchte, stellte sich heraus, dass er schon verbrannt worden war. Da wurde Mose zornig auf Eleasar und Itamar, die Söhne, die Aaron geblieben waren." },
      { number: 17, text: "\"Warum habt ihr das Sündopfer nicht an geweihter Stätte gegessen? Es ist doch höchst heilig! Jahwe hat es euch gegeben, um die Schuld von der Gemeinschaft wegzunehmen, indem ihr Sühne für sie erwirkt." },
      { number: 18, text: "Sein Blut ist nicht ins Heiligtum hineingebracht worden. Ihr hättet es auf jeden Fall im Heiligtum essen sollen, wie ich es angewiesen habe.\"" },
      { number: 19, text: "Aaron erwiderte Mose: \"Du weißt doch, dass meine Söhne ihr Sünd- und Brandopfer Jahwe gebracht haben. Und da ist mir so etwas zugestoßen*. Meinst du, es hätte Jahwe gefallen, wenn ich heute das Sündopfer gegessen hätte?\"", footnotes: ["zugestoßen. Er hatte mit einem Schlag zwei seiner Söhne verloren."] },
      { number: 20, text: "Als Mose das hörte, gab er sich zufrieden." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron:", heading: "Die Reinigung (11-16)\nReine und unreine Tiere" },
      { number: 2, text: "\"Gebt den Israeliten weiter: Folgende Landtiere dürft ihr essen:" },
      { number: 3, text: "Alle, die deutlich gespaltene Hufe haben und ihre Nahrung wiederkäuen." },
      { number: 4, text: "Es gibt aber einige von den wiederkäuenden Arten, die ihr nicht essen dürft, weil sie keine gespaltenen Hufe haben. Sie sollen euch als unrein gelten. Dazu gehört das Kamel," },
      { number: 5, text: "der Klippdachs" },
      { number: 6, text: "und der Hase*.", footnotes: ["Hasen werden zoologisch nicht zu den rinderartigen Wiederkäuern gerechnet, trotzdem kauen sie einen Teil ihrer Nahrung zweimal. Neben ihrem üblichen Kot scheiden sie nämlich von einem Vlies umgebene vitaminreiche Kügelchen aus, so genannte Caecotrophe. Diese werden sofort wieder aufgenommen und an einer bestimmten Stelle des Magens, der Cardiaregion, noch einmal verdaut. Hindert man die Tiere an dieser Form des Wiederkäuens, sterben sie nach kurzer Zeit."] },
      { number: 7, text: "Auch das Schwein soll euch als unrein gelten, denn es hat zwar gespaltene Hufe, käut aber nicht wieder." },
      { number: 8, text: "Ihr dürft nichts von ihrem Fleisch essen und sie auch nicht berühren, wenn sie verendet sind. Sie sollen euch als unrein gelten." },
      { number: 9, text: "Von den Wassertieren dürft ihr alles essen, was Flossen und Schuppen hat, egal ob sie in Flüssen, Seen oder im Meer leben." },
      { number: 10, text: "Aber alles, was keine Flossen oder Schuppen hat und in Süß- oder Salzwasser lebt, jedes andere Lebewesen dort, soll euch etwas Abscheuliches sein." },
      { number: 11, text: "Ihr sollt euch voller Ekel davon abwenden, ihr Fleisch nicht essen und das Verendete verabscheuen." },
      { number: 12, text: "Alle Tiere im Wasser, die keine Flossen und Schuppen haben, sollen für euch etwas Abscheuliches sein." },
      { number: 13, text: "Von den fliegenden Tieren dürfen Folgende nicht gegessen werden, ihr sollt sie verabscheuen: den Gänsegeier, den Lämmergeier und den Mönchsgeier," },
      { number: 14, text: "den Milan und alle Arten von Habichten," },
      { number: 15, text: "alle Arten von Raben," },
      { number: 16, text: "den Strauß, die Schwalbe, die Möwe und alle Arten von Falken," },
      { number: 17, text: "das Käuzchen, die Fischeule und den Uhu," },
      { number: 18, text: "die Schleiereule, die Ohreule und den Aasgeier," },
      { number: 19, text: "den Storch, alle Arten von Reihern, den Wiedehopf und die Fledermaus." },
      { number: 20, text: "Alle geflügelten Insekten, die wie Vierfüßer laufen, sollt ihr verabscheuen," },
      { number: 21, text: "mit Ausnahme derer, die Sprungbeine haben und damit auf der Erde hüpfen können." },
      { number: 22, text: "Von den Folgenden aber dürft ihr alle Arten essen: von den Wanderheuschrecken, den Feldheuschrecken, den Laubheuschrecken und Springheuschrecken." },
      { number: 23, text: "Alles übrige geflügelte vierbeinige Kleingetier sollt ihr verabscheuen." },
      { number: 24, text: "An all den folgenden Tieren verunreinigt ihr euch. Jeder, der ihr Aas berührt, ist bis zum Abend unrein," },
      { number: 25, text: "und jeder, der etwas von dem Aas aufhebt, muss seine Kleidung waschen und ist bis zum Abend unrein." },
      { number: 26, text: "Jedes Tier, das gespaltene, aber nicht ganz gespaltene Klauen hat und nicht wiederkäut, ist unrein für euch. Jeder, der sie berührt, wird unrein." },
      { number: 27, text: "Alle Vierbeiner, die auf Tatzen gehen, sollen euch unrein sein. Jeder, der ihr Aas berührt, wird unrein bis zum Abend." },
      { number: 28, text: "Wer ihr Aas trägt, muss seine Kleidung waschen und ist bis zum Abend unrein. Sie sind für euch unrein." },
      { number: 29, text: "Von den kleinen Landtieren, die auf der Erde wimmeln, sind die Folgenden unrein für euch: der Maulwurf und die Springmaus, alle Arten von Dornschwanzechsen," },
      { number: 30, text: "der Gecko, der Waran, die Eidechse, die Blindschleiche und das Chamäleon." },
      { number: 31, text: "Von dem Kleingetier sind diese also unrein für euch. Jeder, der sie berührt, wenn sie verendet sind, ist bis zum Abend unrein." },
      { number: 32, text: "Und jeder Gegenstand, auf den ein solches totes Tier fällt, wird unrein sein, ob es ein Holzgerät ist, ein Kleid, ein Stück Leder, ein Sack, jeder Gegenstand, mit dem man eine Arbeit verrichtet. Er muss ins Wasser gelegt werden und bleibt unrein bis zum Abend. Dann wird er wieder rein." },
      { number: 33, text: "Fällt solch ein totes Tier in ein Tongefäß, wird alles, was sich darin befindet, unrein, und das Gefäß muss zerschlagen werden." },
      { number: 34, text: "Jede Speise, die man essen will und die mit Wasser aus solch einem Gefäß in Berührung kommt, wird unrein sein. Auch jedes Getränk aus solch einem Gefäß wird unrein." },
      { number: 35, text: "Alles, worauf etwas von dem Aas fällt, wird unrein. Ein Backofen und ein Herd muss eingerissen werden. Sie sind unrein und sollen euch als unrein gelten." },
      { number: 36, text: "Nur Quellen und Zisternen, in denen sich Wasser sammelt, bleiben rein. Wer aber das Aas darin berührt, wird unrein sein." },
      { number: 37, text: "Wenn solches Aas auf Saatgut fällt, bleibt es rein." },
      { number: 38, text: "Wenn man aber Wasser auf das Saatgut gießt und es fällt solches Aas darauf, wird es unrein sein." },
      { number: 39, text: "Und wenn eins von den Tieren verendet, die ihr eigentlich essen dürft, wird derjenige, der das Aas berührt, unrein bis zum Abend." },
      { number: 40, text: "Wer von dem Aas isst, muss seine Kleidung waschen und bleibt unrein bis zum Abend. Wer das Aas aufhebt, muss ebenfalls seine Kleidung waschen und bleibt unrein bis zum Abend." },
      { number: 41, text: "Und alles Kleingetier, das auf der Erde wimmelt, ist etwas Abscheuliches. Es darf nicht gegessen werden." },
      { number: 42, text: "Alles, was auf dem Bauch kriecht, und alles, was auf vier oder mehr Füßen läuft, alles Kleingetier, das auf der Erde wimmelt, dürft ihr nicht essen. Es ist etwas Abscheuliches." },
      { number: 43, text: "Macht euch selbst nicht zu etwas Abscheulichem durch das wimmelnde Kleingetier, verunreinigt euch nicht an ihnen und lasst euch nicht verunreinigen durch sie." },
      { number: 44, text: "Denn ich bin Jahwe, euer Gott. Heiligt euch! Ihr sollt heilig sein, denn ich bin heilig! Und ihr sollt euch nicht selbst verunreinigen durch all das Kleingetier, das sich auf der Erde regt." },
      { number: 45, text: "Denn ich bin Jahwe, der euch aus Ägypten geführt hat, um euer Gott zu sein: So sollt ihr heilig sein, denn ich bin heilig!\"" },
      { number: 46, text: "Das ist die Weisung über das Vieh, die Vögel und alle Lebewesen, die sich im Wasser regen, und alles, was auf der Erde wimmelt," },
      { number: 47, text: "damit man unterscheiden kann zwischen rein und unrein, zwischen Tieren, die gegessen werden dürfen, und solchen, die man nicht essen darf." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Reinheitsvorschriften für Wöchnerinnen" },
      { number: 2, text: "\"Gebt den Israeliten Folgendes weiter: Wenn eine Frau einen Sohn zur Welt bringt, ist sie sieben Tage lang unrein, so wie während ihrer monatlichen Blutung." },
      { number: 3, text: "Am achten Tag soll der Sohn beschnitten* werden.", footnotes: ["beschnitten. Siehe 1. Mose 17,9-14."] },
      { number: 4, text: "Dann soll sie noch 33 Tage zur Reinigung von ihrem Blut zu Hause bleiben. Sie darf nichts Heiliges berühren und nicht ins Heiligtum kommen, bis die Zeit ihrer Reinigung vorbei ist." },
      { number: 5, text: "Wenn sie eine Tochter zur Welt bringt, ist sie zwei Wochen lang unrein, so wie während ihrer monatlichen Blutung. Und 66 Tage soll sie zur Reinigung von ihrem Blut zu Hause bleiben." },
      { number: 6, text: "Wenn die Zeit ihrer Reinigung für einen Sohn oder eine Tochter vorbei ist, soll sie ein einjähriges Lamm als Brandopfer und eine Taube oder eine Turteltaube als Sündopfer zum Priester an den Eingang zum Zelt der Gottesbegegnung bringen." },
      { number: 7, text: "Dieser soll es Jahwe darbringen und Sühne für sie erwirken. Dann wird sie rein von ihrem Blutfluss sein. Das sind die Reinheitsvorschriften für Wöchnerinnen." },
      { number: 8, text: "Reichen ihre Mittel für ein Schaf aber nicht aus, soll sie zwei Turteltauben oder zwei junge Tauben bringen,* eine zum Brandopfer und eine zum Sündopfer. Der Priester soll Sühne für sie erwirken, dann wird sie rein.\"", footnotes: ["Wird im Neuen Testament von Lukas zitiert: Lukas 2,24."] },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron:", heading: "Aussatz an Menschen" },
      { number: 2, text: "\"Wenn sich auf der Haut eines Menschen eine Schwellung, ein schuppiger Ausschlag oder ein heller Fleck bildet und somit der Verdacht auf Aussatz besteht, dann muss er zum Priester gebracht werden, zu Aaron oder einem seiner Söhne." },
      { number: 3, text: "Der Priester muss die befallene Stelle auf der Haut besehen. Hat sich das Haar an dieser Stelle weiß gefärbt und erscheint sie tiefer als die übrige Haut, dann handelt es sich um Aussatz. Wenn der Priester das sieht, soll er denjenigen für unrein erklären." },
      { number: 4, text: "Falls es ein heller Fleck auf seiner Haut ist, der nicht tiefer als die Haut erscheint und dessen Haar nicht weiß geworden ist, dann soll der Priester ihn für sieben Tage isolieren." },
      { number: 5, text: "Am siebten Tag soll der Priester ihn untersuchen. Wenn der Fleck in seinen Augen unverändert ist und nicht um sich gegriffen hat, soll der Priester ihn für weitere sieben Tage isolieren." },
      { number: 6, text: "Am siebten Tag soll der Priester ihn noch einmal untersuchen. Ist der Fleck dann blass geworden und hat sich auf der Haut nicht ausgebreitet, soll der Priester ihn für rein erklären. Es ist ein Ausschlag. Derjenige soll seine Kleidung waschen und ist dann rein." },
      { number: 7, text: "Wenn der Ausschlag auf der Haut sich aber ausgebreitet hat, nachdem der Betreffende sich dem Priester zeigte, dann muss er sich dem Priester ein zweites Mal zeigen." },
      { number: 8, text: "Der Priester soll es untersuchen. Wenn sich der Ausschlag auf der Haut ausgebreitet hat, muss der Priester ihn für unrein erklären." },
      { number: 9, text: "Wenn sich ein Aussatzmal bei einem Menschen bildet, dann soll er zum Priester gebracht werden." },
      { number: 10, text: "Stellt der Priester fest, dass sich eine weiße Schwellung auf der Haut zeigt, dass die Haare heller geworden sind und sich an dieser Stelle eine Wucherung aus rohem Fleisch befindet," },
      { number: 11, text: "dann ist das ein fortgeschrittener Aussatz auf seiner Haut. Der Priester braucht ihn nicht erst zu isolieren, sondern muss ihn gleich für unrein erklären, denn er ist unrein." },
      { number: 12, text: "Breitet sich der Aussatz aber über die ganze Haut aus und bedeckt den Kranken von Kopf bis Fuß, soweit der Priester es sehen kann," },
      { number: 13, text: "soll er es untersuchen. Wenn der Aussatz den ganzen Körper bedeckt, soll er den Kranken für rein erklären. Weil die ganze Haut weiß geworden ist, gilt er als rein." },
      { number: 14, text: "Sobald sich aber eine Wucherung an ihm zeigt, ist er unrein." },
      { number: 15, text: "Wenn der Priester die Wucherung sieht, soll er ihn für unrein erklären. Es ist Aussatz." },
      { number: 16, text: "Wenn die Wucherung zurückgeht und weiß wird, soll der Kranke zum Priester kommen," },
      { number: 17, text: "und der Priester soll ihn untersuchen. Wenn die Stelle weiß geworden ist, soll er ihn für rein erklären. Er ist rein." },
      { number: 18, text: "Wenn auf der Haut eines Menschen ein Geschwür entsteht und wieder abheilt," },
      { number: 19, text: "aber an der Stelle des Geschwürs bildet sich eine weiße Erhöhung oder ein weiß-rötlicher Fleck, dann soll derjenige sich dem Priester zeigen." },
      { number: 20, text: "Der Priester soll es untersuchen. Erscheint der Fleck tiefer als die übrige Haut und sind die Haare dort weiß geworden, soll der Priester ihn für unrein erklären. Es ist ein Aussatzmal, das sich in dem Geschwür gebildet hat." },
      { number: 21, text: "Untersucht der Priester aber die Stelle und es findet sich kein weißes Haar darauf und sie ist auch nicht tiefer als die übrige Haut, soll der Priester ihn für sieben Tage isolieren." },
      { number: 22, text: "Hat das Mal sich danach ausgedehnt, muss der Priester den Kranken für unrein erklären. Es ist ein Aussatzmal." },
      { number: 23, text: "Bleibt der Fleck jedoch an seiner Stelle und breitet sich nicht aus, dann ist es die Narbe des Geschwürs, und der Priester soll ihn für rein erklären." },
      { number: 24, text: "Wenn jemand eine Brandwunde auf der Haut hat und darin bildet sich ein weiß-rötlicher oder ein weißer Fleck," },
      { number: 25, text: "soll der Priester ihn untersuchen. Erscheint der Fleck tiefer als die übrige Haut und sind die Haare dort weiß geworden, dann ist Aussatz in der Brandwunde aufgebrochen. Der Priester soll ihn für unrein erklären. Es ist ein Aussatzmal." },
      { number: 26, text: "Untersucht er aber die Stelle und es findet sich kein weißes Haar darauf und sie ist auch nicht tiefer als die übrige Haut, soll er ihn für sieben Tage isolieren." },
      { number: 27, text: "Am siebten Tag soll der Priester ihn wieder untersuchen. Wenn sich der Fleck auf der Haut ausbreitet, soll er ihn für unrein erklären. Es ist ein Aussatzmal." },
      { number: 28, text: "Wenn der Fleck sich nicht ausgebreitet hat und blass aussieht, so ist es eine Schwellung der Brandwunde, und der Priester soll ihn für rein erklären. Es ist nur eine Wundnarbe." },
      { number: 29, text: "Wenn ein Mann oder eine Frau einen Ausschlag auf dem Kopf oder unter dem Bart bekommt," },
      { number: 30, text: "soll der Priester das Übel untersuchen. Erscheint es tiefer liegend als die Haut, und goldglänzende dünne Haare wachsen darauf, dann muss der Priester die Person für unrein erklären. Es ist eine Flechte, ein Aussatz des Kopfes oder Bartes." },
      { number: 31, text: "Wenn der Priester aber die von der Flechte befallene Stelle untersucht und sie nicht tiefer als die übrige Haut erscheint und sich keine schwarzen Haare darauf befinden, dann soll der Priester die Person für sieben Tage isolieren." },
      { number: 32, text: "Am siebten Tag soll er die Stelle wieder untersuchen. Hat die Flechte nicht um sich gegriffen und ist kein goldglänzendes Haar darin und erscheint sie nicht tiefer als die Haut," },
      { number: 33, text: "dann soll die Person sich das Haar rund um die Stelle abrasieren lassen. Der Priester isoliere sie noch einmal sieben Tage." },
      { number: 34, text: "Wenn er die Flechte am siebten Tag untersucht und sie hat nicht um sich gegriffen und erscheint nicht tiefer als die Haut, dann soll er die Person für rein erklären. Sie soll ihre Kleidung waschen und ist rein." },
      { number: 35, text: "Wenn die Flechte nach der Reinigung aber doch um sich greift," },
      { number: 36, text: "soll der Priester die Person noch einmal untersuchen. Wenn die Flechte in der Haut um sich gegriffen hat, muss der Priester nicht nach goldglänzenden Haaren suchen. Die Person ist unrein." },
      { number: 37, text: "Ist die Flechte aber in seinen Augen unverändert geblieben und schwarze Haare sind darin gewachsen, ist die Flechte geheilt. Die Person ist rein und der Priester soll sie für rein erklären." },
      { number: 38, text: "Zeigen sich bei einem Mann oder einer Frau weiße Flecken auf der Haut," },
      { number: 39, text: "soll der Priester sie untersuchen. Sind es nur blassweiße Flecken, dann ist es ein gutartiger Ausschlag, der auf der Haut ausgebrochen ist. Die Person ist rein." },
      { number: 40, text: "Wenn ein Mann auf dem Hinterkopf kahl wird, hat er eine Glatze. Er ist rein." },
      { number: 41, text: "Wenn sein Kopf auf der Vorderseite kahl wird, hat er eine Stirnglatze. Er ist rein." },
      { number: 42, text: "Wenn an den kahlen Stellen hinten oder vorn ein weiß-rötlicher Fleck entsteht, dann ist Aussatz bei ihm ausgebrochen." },
      { number: 43, text: "Der Priester soll ihn untersuchen. Wenn das erhöhte Mal auf seiner hinteren oder vorderen Glatze weiß-rötlich aussieht wie Aussatz auf der Haut," },
      { number: 44, text: "dann ist er ein aussätziger Mann. Der Priester soll ihn unbedingt für unrein erklären. Er hat auf seinem Kopf ein Aussatzmal." },
      { number: 45, text: "Der Aussätzige, an dem ein solches Mal ist, muss zerrissene Kleidung tragen, sein Kopfhaar verwildern lassen und den Lippenbart verhüllen, und er soll rufen: Unrein, unrein." },
      { number: 46, text: "Solange er die Krankheit an sich hat, bleibt er unrein. Er ist unrein und soll abgesondert leben. Seine Wohnung soll außerhalb vom Lager sein.\"" },
      { number: 47, text: "\"Wenn an einem Kleidungsstück aus Leinen oder Wolle ein Aussatzmal entsteht", heading: "Aussatz an der Kleidung" },
      { number: 48, text: "oder an einem gewebten oder gewirkten Stoff aus Leinen oder Wolle oder an Leder oder etwas, das aus Leder angefertigt ist," },
      { number: 49, text: "und das Mal am Kleidungsstück, am Leder, am gewebten oder gewirkten Stoff oder am ledernen Gegenstand ist grünlich oder rötlich, dann ist es ein Aussatzmal und muss dem Priester gezeigt werden." },
      { number: 50, text: "Der Priester untersuche das Mal und schließe das Stück sieben Tage lang ein." },
      { number: 51, text: "Untersucht er es am siebten Tag und sieht, dass das Mal sich am Kleidungsstück, am gewebten oder gewirkten Stoff, am Leder oder am ledernen Gegenstand ausgeweitet hat, dann ist es ein bösartiger Aussatz. Das Stück ist unrein." },
      { number: 52, text: "Man soll das Kleidungsstück oder den gewebten oder gewirkten Stoff aus Wolle oder Leinen oder den ledernen Gegenstand verbrennen, denn es handelt sich um bösartigen Aussatz. Das Stück muss verbrannt werden." },
      { number: 53, text: "Wenn der Priester das Mal untersucht und sieht, dass es auf dem Kleidungsstück, dem gewebten oder gewirkten Stück oder dem ledernen Gegenstand nicht um sich gegriffen hat," },
      { number: 54, text: "dann soll der Priester anordnen, dass man das, woran das Mal ist, wäscht. Dann soll er es noch einmal sieben Tage lang einschließen." },
      { number: 55, text: "Wenn der Priester das Mal nach dem Waschen untersucht und es hat sich nicht verändert, auch nicht um sich gegriffen, ist das Stück dennoch unrein. Es muss verbrannt werden. Es ist eine eingefressene Vertiefung auf seiner Vorder- oder Rückseite." },
      { number: 56, text: "Wenn der Priester das Mal untersucht und es ist nach dem Waschen blass geworden, dann soll er es vom Kleidungsstück, vom Leder, vom Gewebten oder Gewirkten abreißen." },
      { number: 57, text: "Zeigt sich der Befall aber erneut an dem Kleidungsstück, am Gewebten oder Gewirkten oder einem Gegenstand aus Leder, ist es ein neu ausbrechender Aussatz. Dann muss das Stück mit dem Mal verbrannt werden." },
      { number: 58, text: "Aber das Kleidungsstück, der gewebte oder gewirkte Stoff oder ein Gegenstand aus Leder, von denen das Mal nach dem Waschen verschwindet, soll noch einmal gewaschen werden und ist dann rein." },
      { number: 59, text: "Das ist die Weisung für ein Aussatzmal an einem Kleidungsstück aus Wolle oder Leinen oder an einem gewebten oder gewirkten Stoff oder an einem Gegenstand aus Leder, nach der man diese für rein oder unrein erklären muss.\"" },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Reinigungsopfer für Geheilte" },
      { number: 2, text: "\"Folgende Bestimmung gilt für einen Aussätzigen an dem Tag, an dem er für rein erklärt wird: Er muss zum Priester gebracht werden." },
      { number: 3, text: "Dazu muss der Priester nach draußen vor das Lager gehen und den Aussätzigen untersuchen. Wenn das Aussatzmal verheilt ist," },
      { number: 4, text: "lasse der Priester für den, der sich reinigen lässt, zwei reine, lebende Vögel holen, Zedernholz, Karmesin* und Ysop*.", footnotes: ["Karmesin, (scharlach)roter Farbstoff, der aus getrockneten weiblichen Kochenilleläusen gewonnen wird.", "Ysop. Busch mit stark riechenden Blättern."] },
      { number: 5, text: "Der Priester soll den reinen Vogel über einem Tongefäß mit frischem Wasser schlachten lassen." },
      { number: 6, text: "Dann soll er den lebenden Vogel nehmen, das Zedernholz, das Karmesinrot und den Ysopzweig und dies alles, auch den lebenden Vogel, in das Blut des Vogels tauchen, der über dem frischen Wasser geschlachtet wurde." },
      { number: 7, text: "Nun besprenge er den, der vom Aussatz zu reinigen ist, sieben Mal damit und reinige ihn so. Den lebenden Vogel lasse er fortfliegen." },
      { number: 8, text: "Der, der sich reinigen lässt, soll seine Kleidung waschen, alle seine Haare scheren und sich mit Wasser übergießen. Dann ist er rein. Danach darf er ins Lager kommen, muss aber noch sieben Tage außerhalb seines Zeltes zubringen." },
      { number: 9, text: "Am siebten Tag soll er wieder sein Haar scheren, seinen Kopf, seinen Bart, seine Augenbrauen und all sein übriges Haar. Er soll seine Kleidung waschen und sich mit Wasser übergießen. Dann ist er rein." },
      { number: 10, text: "Am achten Tag soll er zwei makellose männliche Schaflämmer und ein fehlerloses einjähriges weibliches Lamm nehmen, dazu sieben Liter* Feinmehl, das mit Öl zum Speisopfer angerührt ist, und ein drittel Liter* Olivenöl.", footnotes: ["sieben Liter. Wörtlich: drei Zehntel (Efa).", "ein drittel Liter. Wörtlich: ein Log. Die vermutlich kleine Maßeinheit kommt nur in diesem Kapitel vor."] },
      { number: 11, text: "Der Priester, der die Reinigung vollzieht, soll den Mann mit seinen Opfergaben an den Eingang zum Zelt der Gottesbegegnung bringen." },
      { number: 12, text: "Dann soll der Priester das eine männliche Lamm nehmen und es zusammen mit dem drittel Liter Olivenöl als Schuldopfer darbringen. Er schwinge sie als Weihgabe vor Jahwe hin und her" },
      { number: 13, text: "und schlachte das Lamm an der Stelle, wo man das Sünd- und Brandopfer schlachtet, an heiligem Ort. Genau wie das Sündopfer gehört das Schuldopfer dem Priester. Es ist höchst heilig." },
      { number: 14, text: "Der Priester nehme etwas von dem Blut des Schuldopfers und betupfe damit das rechte Ohrläppchen, den rechten Daumen und die rechte große Zehe von dem, der zu reinigen ist." },
      { number: 15, text: "Dann gieße er sich etwas von dem Öl in die hohle linke Hand," },
      { number: 16, text: "tauche seinen rechten Finger hinein und versprenge damit siebenmal etwas vor Jahwe." },
      { number: 17, text: "Dann betupfe er damit das rechte Ohrläppchen, den rechten Daumen und die rechte große Zehe von dem, der zu reinigen ist," },
      { number: 18, text: "und streiche ihm den Rest davon auf den Kopf." },
      { number: 19, text: "Dann soll der Priester das Sündopfer für ihn darbringen. Danach schlachte er das Brandopfer." },
      { number: 20, text: "Das Brand- und Speisopfer bringe er auf den Altar. So erwirke er Sühne für den Betreffenden, dann ist er rein." },
      { number: 21, text: "Wenn er arm ist und seine Mittel dafür nicht ausreichen, dann soll er ein Lamm als Schuldopfer nehmen, als Weihgabe, um Sühne für sich zu erwirken. Als Speisopfer bringe er zwei Liter Feinmehl, das er mit Öl angerührt hat und ein drittel Liter Öl," },
      { number: 22, text: "dazu zwei Turteltauben oder zwei junge Tauben, was er eben aufbringen kann, die eine als Sündopfer, die andere als Brandopfer." },
      { number: 23, text: "Er bringe dies alles zu seiner Reinigung am achten Tag vor den Priester an den Eingang zum Zelt der Gottesbegegnung und trete damit vor Jahwe." },
      { number: 24, text: "Der Priester nehme das Lamm des Schuldopfers und das Öl und schwinge es als Weihgabe vor Jahwe hin und her." },
      { number: 25, text: "Dann schlachte er das Lamm für das Schuldopfer. Er nehme etwas von dessen Blut und betupfe damit das rechte Ohrläppchen, den rechten Daumen und die rechte große Zehe von dem, der zu reinigen ist." },
      { number: 26, text: "Dann gieße er sich etwas von dem Öl in die hohle linke Hand," },
      { number: 27, text: "versprenge mit seinem rechten Finger siebenmal etwas davon vor Jahwe." },
      { number: 28, text: "Dann betupfe er damit das rechte Ohrläppchen, den rechten Daumen und die rechte große Zehe von dem, der zu reinigen ist, dorthin, wo auch das Blut vom Schuldopfer kam." },
      { number: 29, text: "Den Rest davon streiche er dem, der zu reinigen ist, auf den Kopf, um Sühne für ihn zu erwirken." },
      { number: 30, text: "Dann soll dieser zusammen mit dem Speisopfer eine von den Turteltauben oder den Jungtauben, die er sich leisten konnte, bringen," },
      { number: 31, text: "die eine als Sündopfer, die andere als Brandopfer; und der Priester erwirke Sühne für ihn." },
      { number: 32, text: "Das ist die Anordnung für den, der ein Aussatzmal hat, wenn seine Mittel zur Reinigung nicht für mehr ausreichen.\"" },
      { number: 33, text: "Jahwe sagte zu Mose und Aaron:", heading: "Aussatz an Häusern" },
      { number: 34, text: "\"Wenn ihr in das Land Kanaan kommt, das ich euch zum Besitz gebe, und ich ein Aussatzmal an ein Haus eures Landbesitzes kommen lasse," },
      { number: 35, text: "dann muss der Besitzer des Hauses zum Priester gehen und melden: 'An meinem Haus zeigt sich etwas wie ein Aussatzmal.'" },
      { number: 36, text: "Der Priester muss das Haus ausräumen lassen, bevor er hineingeht, um das Mal zu untersuchen, damit nicht alles unrein wird, was sich im Haus befindet. Erst danach geht er hinein und sieht sich das Haus an." },
      { number: 37, text: "Stellt er fest, dass an den Wänden grünliche oder rötliche Flecken sind, die tiefer erscheinen als die übrige Wand," },
      { number: 38, text: "dann soll er hinausgehen und das Haus für sieben Tage versperren." },
      { number: 39, text: "Am siebten Tag soll der Priester wiederkommen und das Haus untersuchen. Wenn sich das Mal an den Wänden des Hauses ausgebreitet hat," },
      { number: 40, text: "soll er die befallenen Steine herausbrechen und außerhalb der Stadt an einen unreinen Platz bringen lassen." },
      { number: 41, text: "Dann muss das Haus innen vollständig abgekratzt werden. Den abgekratzten Lehm muss man ebenfalls vor die Stadt an den unreinen Platz bringen." },
      { number: 42, text: "Dann soll man andere Steine anstelle der alten einsetzen und das Haus neu verputzen." },
      { number: 43, text: "Wenn das Mal dann aber von neuem erscheint, obwohl man die alten Steine entfernt, das Haus abgekratzt und neu verputzt hat," },
      { number: 44, text: "muss der Priester wiederkommen. Wenn sich das Mal am Haus ausgebreitet hat, ist es ein bösartiger Aussatz am Haus. Es ist unrein" },
      { number: 45, text: "und muss niedergerissen werden. Steine, Holz und aller Lehmputz muss an einen unreinen Platz außerhalb der Stadt geschafft werden." },
      { number: 46, text: "Wenn jemand das Haus betritt, während es abgesperrt ist, wird er unrein bis zum Abend." },
      { number: 47, text: "Wer in dem Haus schläft oder isst, soll seine Kleidung waschen." },
      { number: 48, text: "Wenn der Priester aber hineinkommt und feststellt, dass das Mal, nachdem der Putz erneuert wurde, nicht wieder aufgetreten ist, dann soll er das Haus für rein erklären, denn der Befall ist beseitigt." },
      { number: 49, text: "Um das Haus zu entsündigen, soll er zwei Vögel, Zedernholz, Karmesin und Ysop herbeibringen." },
      { number: 50, text: "Er schlachte den einen Vogel über einem Tongefäß mit frischem Wasser." },
      { number: 51, text: "Dann soll er das Zedernholz nehmen, den Ysop, die Karmesinfarbe und den lebenden Vogel und alles zusammen in das Blut des geschlachteten Vogels und das frische Wasser tauchen und dann damit das Haus siebenmal besprengen." },
      { number: 52, text: "So entsündigt er das Haus mit dem Blut des Vogels, mit dem frischen Wasser, dem lebenden Vogel, dem Zedernholz, dem Ysop und dem Karmesin." },
      { number: 53, text: "Dann soll er den lebenden Vogel aus der Stadt hinaus ins offene Feld fliegen lassen. So erwirkt er Sühne für das Haus, und es wird rein." },
      { number: 54, text: "Das ist die Weisung, die für jedes Aussatzmal und jede Flechte gilt," },
      { number: 55, text: "für den Aussatz an Kleidung und Häusern," },
      { number: 56, text: "für Schwellungen, den schuppigen Ausschlag und die hellen Flecken," },
      { number: 57, text: "damit man beurteilen kann, wann etwas für rein oder unrein zu erklären ist. Das ist die Weisung für Aussatz.\"" },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron:", heading: "Unreinheit bei Männern" },
      { number: 2, text: "\"Gib den Israeliten Folgendes weiter: Jeder Mann, der einen krankhaften Ausfluss aus seinem Glied hat, wird dadurch unrein." },
      { number: 3, text: "Hat er diesen Ausfluss, so bleibt die Unreinheit bestehen, ob sein Glied den Ausfluss fließen lässt oder ihn zurückhält." },
      { number: 4, text: "Alles, worauf der Kranke liegt oder sitzt, wird unrein." },
      { number: 5, text: "Wer dessen Lager berührt, soll seine Kleidung waschen und sich mit Wasser übergießen. Er wird bis zum Abend unrein sein." },
      { number: 6, text: "Wer sich auf einen Gegenstand setzt, auf dem der an Ausfluss Leidende zu sitzen pflegt, soll seine Kleidung waschen und sich mit Wasser übergießen. Er wird bis zum Abend unrein sein." },
      { number: 7, text: "Auch wer den Körper des Kranken berührt, soll seine Kleidung waschen und sich mit Wasser übergießen. Er wird bis zum Abend unrein sein." },
      { number: 8, text: "Und wenn der Kranke einen Reinen anspuckt, soll dieser seine Kleidung waschen und sich mit Wasser übergießen. Er wird bis zum Abend unrein sein." },
      { number: 9, text: "Jeder Sattel, auf dem der an Ausfluss Leidende sitzt, ist unrein." },
      { number: 10, text: "Jeder, der irgendetwas berührt, was dieser unter sich hatte, wird bis zum Abend unrein sein. Und wer es trägt, soll seine Kleidung waschen und sich mit Wasser übergießen. Er wird bis zum Abend unrein sein." },
      { number: 11, text: "Und jeder, der den an Ausfluss Leidenden berührt, ohne sich anschließend die Hände abzuspülen, muss seine Kleidung waschen und sich mit Wasser übergießen. Er wird bis zum Abend unrein sein." },
      { number: 12, text: "Jedes Tongefäß, das der Kranke berührt, muss zerschlagen und jedes Holzgefäß muss im Wasser abgespült werden." },
      { number: 13, text: "Wird dieser Mann von seinem Ausfluss rein, dann soll er noch sieben Tage auf seine Reinigung warten. Er soll seine Kleidung waschen und sich mit frischem Wasser übergießen. Dann wird er rein sein." },
      { number: 14, text: "Am achten Tag nehme er sich zwei Turteltauben oder zwei junge Tauben, komme an den Eingang zum Zelt der Gottesbegegnung vor Jahwe und übergebe sie dem Priester." },
      { number: 15, text: "Der Priester soll sie opfern, eine als Sündopfer und eine als Brandopfer. So erwirke der Priester vor Jahwe Sühne für ihn wegen seines Ausflusses." },
      { number: 16, text: "Wenn ein Mann einen Samenerguss hat, soll er sich mit Wasser übergießen und ist unrein bis zum Abend." },
      { number: 17, text: "Und jedes Kleidungs- und Lederstück, auf das etwas von dem Samenerguss gekommen ist, soll im Wasser gewaschen werden. Es ist bis zum Abend unrein." },
      { number: 18, text: "Und wenn ein Mann mit einer Frau schläft und dabei einen Samenerguss hat, sollen sich beide mit Wasser übergießen und sind bis zum Abend unrein." },
      { number: 19, text: "Wenn eine Frau einen Ausfluss hat und Blut aus ihrer Scheide fließt, ist sie sieben Tage lang unrein. Jeder, der sie berührt, wird bis zum Abend unrein sein.", heading: "Unreinheit bei Frauen" },
      { number: 20, text: "Alles, worauf sie sich während ihrer monatlichen Blutung legt oder setzt, wird unrein sein." },
      { number: 21, text: "Wer ihr Lager berührt, muss seine Kleidung waschen und sich mit Wasser übergießen und ist bis zum Abend unrein." },
      { number: 22, text: "Jeder, der einen Gegenstand berührt, worauf sie zu sitzen pflegt, muss seine Kleidung waschen und sich mit Wasser übergießen und ist bis zum Abend unrein." },
      { number: 23, text: "Auch wer irgendetwas auf ihrem Lager oder ihrer Sitzgelegenheit berührt, wird bis zum Abend unrein sein." },
      { number: 24, text: "Hat ein Mann Geschlechtsverkehr mit ihr, kommt ihre Unreinheit auch auf ihn. Dann wird auch er sieben Tage lang unrein und alles, worauf er liegt, wird unrein." },
      { number: 25, text: "Wenn eine Frau Blutungen außerhalb ihrer monatlichen Regel oder über die normale Zeit hinaus hat, ist sie während dieser Zeit genauso unrein wie während ihrer Monatsblutung.*", footnotes: ["unrein ... Monatsblutung. Das war der Zustand jener Frau, die Jesus berührte (Matthäus 9,20; Markus 5,25)."] },
      { number: 26, text: "Jedes Lager, auf dem sie liegt, und jeder Gegenstand, auf den sie sich setzt, wird dann unrein wie während ihrer Regel." },
      { number: 27, text: "Und jeder, der diese Dinge berührt, wird unrein. Er muss seine Kleidung waschen und sich mit Wasser übergießen und ist bis zum Abend unrein." },
      { number: 28, text: "Ist die Frau rein geworden von ihrem Ausfluss, soll sie sieben Tage abwarten, dann ist sie rein." },
      { number: 29, text: "Am achten Tag nehme sie sich zwei Turteltauben oder zwei junge Tauben und bringe sie zum Priester an den Eingang zum Zelt der Gottesbegegnung." },
      { number: 30, text: "Der Priester soll sie opfern, eine als Sündopfer und eine als Brandopfer. So erwirke er Sühne vor Jahwe für sie wegen ihres unreinen Ausflusses." },
      { number: 31, text: "Ihr sollt die Israeliten vor ihrer eigenen Unreinheit warnen, damit sie nicht ihrer Unreinheit wegen sterben, wenn sie meine Wohnung, die unter ihnen ist, verunreinigen." },
      { number: 32, text: "Das ist die Weisung für einen Mann, der durch einen Ausfluss oder einen Samenerguss unrein wurde," },
      { number: 33, text: "und für die Frau, die ihre monatliche Blutung hat, und für alle, die einen Ausfluss haben, Mann oder Frau, und für den Mann, der mit einer unrein gewordenen Frau schläft.\"" },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Nach dem Tod der beiden Söhne Aarons, die starben, als sie in die Nähe Jahwes kamen, redete Jahwe zu Mose.", heading: "Der Versöhnungstag" },
      { number: 2, text: "Er sagte zu ihm: \"Sprich mit deinem Bruder Aaron, dass er nicht zu jeder Zeit ins Heiligtum hinter den Vorhang geht, vor die Deckplatte auf der Lade. Sonst muss er sterben. Denn ich zeige mich in der Wolke über der Deckplatte." },
      { number: 3, text: "Er darf nur ins Heiligtum hineingehen, wenn er vorher einen jungen Stier als Sündopfer und einen Schafbock als Brandopfer dargebracht hat." },
      { number: 4, text: "Er soll ein Priesterhemd aus Leinen anhaben und leinene Kniehosen tragen, die seine Scham bedecken. Auch Gürtel und Kopfbund müssen aus Leinen bestehen. Es sind heilige Gewänder. Bevor er sie anzieht, muss er sich mit Wasser übergießen." },
      { number: 5, text: "Von der Gemeinschaft der Israeliten lasse er sich zwei Ziegenböcke für das Sündopfer und einen Schafbock für das Brandopfer geben." },
      { number: 6, text: "Für sich selbst soll er den Stier des Sündopfers bereithalten, mit dem er Sühne für sich und seine Familie erwirkt." },
      { number: 7, text: "Die beiden Ziegenböcke bringe er vor Jahwe an den Eingang vom Zelt der Gottesbegegnung." },
      { number: 8, text: "Dann soll er das Los entscheiden lassen, welcher Bock für Jahwe und welcher für Asasel* bestimmt ist.", footnotes: ["Asasel könnte ein Eigenname für eine teuflische Macht sein, sodass die Sünden symbolisch zu ihrem eigentlichen Urheber zurückgeschickt wurden. Die LXX deutet den Begriff, der nur hier vorkommt, als \"Ziegenbock der Vertreibung\", andere meinen, es wäre ein abstrakter Begriff für \"völlige Beseitigung\". Von der im Text beschriebenen Handlungsweise kommt der Begriff \"Sündenbock\"."] },
      { number: 9, text: "Den Ziegenbock, auf den das Los für Jahwe gefallen ist, soll Aaron als Sündopfer schlachten." },
      { number: 10, text: "Der Ziegenbock, auf den das Los für Asasel gefallen ist, soll lebend vor Jahwe gestellt werden, damit man über ihm die Sühnehandlung vollziehe und ihn dann für Asasel in die Wüste treibe." },
      { number: 11, text: "Aaron soll nun den jungen Stier darbringen, der als Sündopfer für ihn bestimmt ist. Er soll ihn schlachten und Sühne für sich und seine Familie erwirken." },
      { number: 12, text: "Dann nehme er von dem Altar, der vor Jahwe steht, eine Räucherpfanne voll glühender Kohlen, dazu zwei Handvoll von der zerstoßenen wohlriechenden Weihrauchmischung und bringe es in den Raum innerhalb des Vorhangs." },
      { number: 13, text: "Dort, vor Jahwe, streue er den Weihrauch über die Glut, damit der aufsteigende Rauch die Deckplatte über der Lade mit dem Bundesgesetz verhüllt und er nicht sterben muss." },
      { number: 14, text: "Dann nehme er etwas von dem Blut des jungen Stiers und sprenge es mit dem Finger auf die Vorderseite der Deckplatte in Richtung Osten und siebenmal vor ihr auf den Boden." },
      { number: 15, text: "Danach schlachte er den Ziegenbock für das Sündopfer, das für das Volk bestimmt ist, und bringe dessen Blut hinter den Vorhang. Davon sprenge er etwas auf die Deckplatte und vor sie hin, wie er es mit dem Blut des Stiers getan hat." },
      { number: 16, text: "Auf diese Weise erwirke er Sühne für das Heiligtum wegen der Unreinheiten der Israeliten und ihrer Vergehen, mit denen sie sich versündigt haben. Ebenso soll er mit dem Zelt der Gottesbegegnung verfahren, das bei ihnen steht, mitten in ihren Unreinheiten." },
      { number: 17, text: "Kein Mensch darf im Zelt der Gottesbegegnung sein, wenn Aaron hineingeht, um im Heiligtum die Sühnehandlung zu vollziehen, bis er wieder herauskommt. Auf diese Weise soll er Sühne erwirken für sich, seine Familie und die ganze Versammlung Israels." },
      { number: 18, text: "Dann soll er zu dem Altar hinausgehen, der vor Jahwe steht, und für ihn die Sühnehandlung vollziehen. Er nehme etwas von dem Blut des Stiers und dem des Ziegenbocks und bestreiche damit die Hörner des Altars." },
      { number: 19, text: "Dann sprenge er mit seinem Finger siebenmal etwas von dem Blut an den Altar. So soll er ihn von den Unreinheiten der Israeliten reinigen und ihn heiligen." },
      { number: 20, text: "Wenn Aaron die Sühnehandlung für das Heiligtum, das Zelt der Gottesbegegnung und den Altar vollzogen hat, soll er den lebenden Ziegenbock herbeibringen." },
      { number: 21, text: "Er stütze beide Hände auf den Kopf dieses Ziegenbocks und bekenne über ihm alle Schuld der Israeliten und all ihre Vergehen, mit denen sie sich schuldig gemacht haben. Er soll sie auf den Kopf des Bocks legen und ihn dann durch einen bereitstehenden Mann in die Wüste schaffen lassen," },
      { number: 22, text: "damit der Ziegenbock all ihre Schuld mit sich in die Öde trägt. Dann schicke er den Bock in die Wüste." },
      { number: 23, text: "Anschließend soll Aaron in das Zelt der Gottesbegegnung gehen und die Kleidungsstücke aus Leinen ausziehen, die er angezogen hatte, als er in das Heiligtum hineinging, und soll sie dort niederlegen." },
      { number: 24, text: "Dann soll er sich an heiliger Stätte mit Wasser übergießen und seine eigene Kleidung anziehen. Er soll anschließend herauskommen und das Brandopfer für sich und das Volk darbringen, um so für sich und das Volk Sühne zu erwirken." },
      { number: 25, text: "Auch die Fettstücke des Sündopfers soll er auf dem Altar in Rauch aufgehen lassen." },
      { number: 26, text: "Der Mann, der den Ziegenbock zu Asasel hinausgetrieben hat, soll seine Kleidung waschen und sich mit Wasser übergießen, bevor er wieder ins Lager zurückkommt." },
      { number: 27, text: "Die Reste von dem jungen Stier und dem Ziegenbock für das Sündopfer, deren Blut ins Heiligtum gebracht wurde, um Sühne zu erwirken, bringe man vor das Lager. Dort soll man ihre Häute, ihr Fleisch und ihre Eingeweide verbrennen." },
      { number: 28, text: "Der, der sie verbrannt hat, soll seine Kleidung waschen und sich selbst mit Wasser übergießen, bevor er wieder ins Lager zurückkommt." },
      { number: 29, text: "Diese Bestimmungen gelten für alle Zukunft. Am 10. Oktober* sollt ihr euch selbst demütigen und dürft an diesem Tag keine Arbeit verrichten. Das gilt auch für die Fremden, die bei euch leben.", footnotes: ["Oktober. Wörtlich: des 7. Monats. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers."] },
      { number: 30, text: "Denn an diesem Tag erwirkt man Sühne für euch, um euch zu reinigen. Vor Jahwe sollt ihr von all euren Sünden rein werden." },
      { number: 31, text: "Ein Sabbat, ein Feiertag ist es für euch, an dem ihr euch selbst demütigen sollt. Das ist eine ewige Ordnung." },
      { number: 32, text: "Die Sühnehandlung soll der Priester vollziehen, den man anstelle seines Vaters gesalbt und eingesetzt hat. Er soll dabei die Gewänder aus Leinen anziehen, die dafür bestimmt sind," },
      { number: 33, text: "und für das gesamte Heiligtum Sühne erwirken, für das Zelt der Gottesbegegnung und den Altar, für die Priester und die ganze Volksversammlung." },
      { number: 34, text: "Das soll eine ewige Ordnung für euch sein, einmal im Jahr Sühne für alle Sünden der Israeliten zu erwirken.\" Aaron führte alles so aus, wie Jahwe es Mose befohlen hatte." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Jahwe sagte dann zu Mose:", heading: "17-27: Das Leben mit dem heiligen Gott\nDie persönliche Heiligung (17-22)\nDas Blutverbot" },
      { number: 2, text: "\"Gib Aaron, seinen Söhnen und allen Israeliten folgende Anordnungen Jahwes weiter:" },
      { number: 3, text: "Jeder Israelit, der ein Rind, ein Schaf oder eine Ziege schlachtet, sei es im Lager oder außerhalb davon," },
      { number: 4, text: "und das Tier nicht an den Eingang zum Zelt der Gottesbegegnung bringt, um es dort vor der Wohnung Jahwes als Opfergabe für ihn zu schlachten, dem soll es als Blutschuld angerechnet werden. Er hat Blut vergossen und muss aus der Mitte seines Volkes entfernt* werden.", footnotes: ["entfernt. Entweder durch Verbannung oder Tod."] },
      { number: 5, text: "Deshalb sollen die Israeliten ihre Opfer, die sie jetzt noch auf dem freien Feld schlachten, zu Jahwe an den Eingang zum Zelt der Gottesbegegnung bringen und ihm als Freudenopfer schlachten." },
      { number: 6, text: "Der Priester soll das Blut an den Altar Jahwes vor dem Zelt der Gottesbegegnung sprengen und das Fett in Rauch aufgehen lassen als einen Geruch, der Jahwe befriedigt." },
      { number: 7, text: "Sie sollen ihre Tiere nicht mehr als Opfer für die Dämonen schlachten, denen sie nachlaufen. Das ist eine ewige Ordnung für alle ihre Generationen." },
      { number: 8, text: "Weiter sollst du ihnen sagen: Jeder Israelit und jeder Fremde, der unter ihnen lebt, der ein Brand- oder Schlachtopfer darbringt" },
      { number: 9, text: "und es nicht zum Eingang vom Zelt der Gottesbegegnung bringt, um es Jahwe zu opfern, soll von seinem Volk beseitigt werden." },
      { number: 10, text: "Genauso geht es jedem Israeliten und jedem Fremden unter euch, der irgendwelches Blut isst. Ich selbst wende mich gegen jede Person, die Blut isst, und werde sie aus ihrem Volk beseitigen." },
      { number: 11, text: "Denn das Leben des Körpers ist in seinem Blut. Ich habe bestimmt, dass es auf den Altar gegeben wird, um Sühne für euch zu erwirken. Denn das Blut bewirkt Sühne durch das Leben darin." },
      { number: 12, text: "Darum habe ich zu den Israeliten gesagt: Niemand von euch darf Blut essen, auch die Fremden nicht, die bei euch leben." },
      { number: 13, text: "Und jeder von den Israeliten oder den Fremden, die bei euch leben, der Wild oder Vögel jagt, die ihr essen dürft, soll ihr Blut ausfließen lassen und es mit Erde bedecken." },
      { number: 14, text: "Denn das Leben allen Fleisches ist sein Blut, und ich habe zu den Israeliten gesagt: Es ist euch nicht erlaubt, das Blut irgendeines Wesens aus Fleisch zu essen, denn das Leben allen Fleisches ist sein Blut. Jeder, der es isst, muss beseitigt werden." },
      { number: 15, text: "Und jeder, der ein verendetes oder gerissenes Tier isst, er sei Einheimischer oder Fremder, muss seine Kleidung waschen und sich mit Wasser übergießen und bleibt bis zum Abend unrein." },
      { number: 16, text: "Wenn er seine Kleidung nicht wäscht und seinen Körper nicht mit Wasser übergießt, muss er seine Schuld tragen.\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Jahwe sagte weiter zu Mose:", heading: "Verbotene sexuelle Beziehungen" },
      { number: 2, text: "\"Sprich zu den Israeliten: Ich bin Jahwe, euer Gott!" },
      { number: 3, text: "Lebt nicht nach den Sitten des Landes Ägypten, wo ihr gewohnt habt, auch nicht nach den Gewohnheiten des Landes Kanaan, wohin ich euch bringe. Ihr sollt nicht nach ihren Ordnungen leben." },
      { number: 4, text: "Meine Vorschriften sollt ihr befolgen und euch nach meinen Ordnungen richten! Ich bin Jahwe, euer Gott!" },
      { number: 5, text: "Ihr sollt euch nach meinen Vorschriften und Ordnungen richten. Wer sie befolgt, wird durch sie leben.* Ich bin Jahwe!", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 10,5; Galater 3,12."] },
      { number: 6, text: "Niemand von euch soll mit einem seiner Blutsverwandten eine sexuelle Beziehung haben. Ich bin Jahwe!" },
      { number: 7, text: "Die Scham deines Vaters und die Scham deiner Mutter sollst du nicht entblößen. Es ist deine Mutter und du sollst ihre Scham nicht entblößen." },
      { number: 8, text: "Die Scham der Frau deines Vaters sollst du nicht entblößen, es ist die Scham deines Vaters." },
      { number: 9, text: "Die Scham deiner Schwester, der Tochter deines Vaters oder deiner Mutter, sollst du nicht entblößen, egal ob sie in der Familie oder außerhalb von ihr geboren wurde." },
      { number: 10, text: "Die Scham deiner Enkeltochter sollst du nicht entblößen, denn es ist deine eigene Scham." },
      { number: 11, text: "Die Scham der Tochter von einer der Frauen deines Vaters sollst du nicht entblößen. Sie ist deine Schwester." },
      { number: 12, text: "Die Scham der Schwester deines Vaters darfst du nicht entblößen. Sie ist die Blutsverwandte deines Vaters." },
      { number: 13, text: "Die Scham der Schwester deiner Mutter darfst du nicht entblößen. Sie ist die Blutsverwandte deiner Mutter." },
      { number: 14, text: "Die Scham des Bruders deines Vaters sollst du nicht entblößen und dich seiner Frau nicht nähern. Sie ist deine Tante." },
      { number: 15, text: "Die Scham deiner Schwiegertochter sollst du nicht entblößen. Sie ist die Frau deines Sohnes." },
      { number: 16, text: "Die Scham der Frau deines Bruders sollst du nicht entblößen, es ist die Scham deines Bruders." },
      { number: 17, text: "Du sollst nicht die Scham einer Frau und ihrer Tochter entblößen. Die Tochter ihres Sohnes oder ihrer Tochter sollst du nicht nehmen und ihre Scham entblößen. Sie sind deine Blutsverwandten. Es wäre eine Schandtat." },
      { number: 18, text: "Und solange eine Frau lebt, sollst du ihre Schwester nicht zur Nebenfrau nehmen und ihre Scham neben ihr entblößen." },
      { number: 19, text: "Du darfst dich einer Frau, die wegen ihrer monatlichen Blutung unrein ist, nicht nähern und ihre Scham entblößen." },
      { number: 20, text: "Mit der Frau eines anderen Mannes darfst du nicht schlafen, denn dadurch wirst du unrein." },
      { number: 21, text: "Keinen von deinen Nachkommen darfst du dem Moloch* als Opfer verbrennen. Du sollst den Namen deines Gottes nicht entweihen. Ich bin Jahwe!", footnotes: ["Moloch war ein ammonitischer Götze, dem Kinder geopfert wurden."] },
      { number: 22, text: "Du darfst mit keinem anderen Mann* Geschlechtsverkehr haben. Das verabscheue ich.", footnotes: ["Mann. Wörtlich: männlichen. Gemeint ist ein Mensch männlichen Geschlechts, gleich welchen Alters."] },
      { number: 23, text: "Du sollst nicht mit einem Tier Geschlechtsverkehr haben. Dadurch verunreinigst du dich. Und eine Frau soll sich nicht vor ein Tier stellen, um sich mit ihm zu paaren. Das ist schändlich." },
      { number: 24, text: "Verunreinigt euch nicht durch solche Dinge! Denn durch all dieses haben sich die Völker verunreinigt, die ich vor euch vertreibe." },
      { number: 25, text: "Sie haben das Land unrein gemacht, und ich habe es zur Rechenschaft gezogen, sodass es seine Bewohner ausgespuckt hat." },
      { number: 26, text: "Ihr aber sollt euch an meine Ordnungen und Vorschriften halten, ebenso die Fremden, die bei euch leben. Tut nicht solch abscheuliche Dinge" },
      { number: 27, text: "wie die Menschen, die vor euch im Land waren. Denn dadurch ist das Land unrein geworden." },
      { number: 28, text: "Sonst wird euch das Land ebenso ausspucken, wie es das Volk ausgespuckt hat, das vor euch da war." },
      { number: 29, text: "Jeder, der irgendetwas von diesen Abscheulichkeiten tut, soll von seinem Volk beseitigt werden." },
      { number: 30, text: "Gehorcht also meinen Anweisungen, keine dieser abscheulichen Bräuche zu übernehmen, die man vor euch ausgeübt hat, und verunreinigt euch nicht durch sie. Ich bin Jahwe, euer Gott.\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Jahwe sagte weiter zu Mose:", heading: "Heiligung des täglichen Lebens" },
      { number: 2, text: "\"Gib der ganzen Versammlung der Israeliten Folgendes weiter: Ihr sollt heilig sein, denn ich, Jahwe, euer Gott, bin heilig.*", footnotes: ["Wird im Neuen Testament von Petrus zitiert: 1. Petrus 1,16."] },
      { number: 3, text: "Jeder von euch soll seine Mutter und seinen Vater ehren. Haltet meine Sabbate ein. Ich bin Jahwe, euer Gott." },
      { number: 4, text: "Ihr sollt euch nicht den Götzen zuwenden und euch auch keine Götter aus Metall gießen. Ich bin Jahwe, euer Gott!" },
      { number: 5, text: "Wenn ihr Jahwe ein Freudenopfer schlachtet, sollt ihr es so tun, dass ihr Wohlwollen findet." },
      { number: 6, text: "Es muss am Tag der Schlachtung gegessen werden und auch noch am Tag danach. Wenn am dritten Tag noch etwas übrig ist, muss es verbrannt werden." },
      { number: 7, text: "Wird noch am dritten Tag von dem Fleisch gegessen, ist es unrein geworden und das Opfer wird nicht mein Gefallen finden." },
      { number: 8, text: "Wer davon isst, lädt Schuld auf sich, denn er hat entweiht, was Jahwe heilig ist. Diese Person muss von ihrem Volk beseitigt werden." },
      { number: 9, text: "Wenn ihr eure Ernte einbringt, sollst du das Feld nicht bis an den Rand abernten. Du sollst auch keine Nachlese halten." },
      { number: 10, text: "Auch in deinem Weinberg sollst du nicht nachlesen und das Heruntergefallene nicht aufheben. Lass es für die Armen und Fremden übrig. Ich bin Jahwe, euer Gott!" },
      { number: 11, text: "Ihr sollt nicht stehlen, nicht lügen und einander nicht betrügen." },
      { number: 12, text: "Missbraucht meinen Namen nicht, um falsch zu schwören, denn damit entweiht ihr ihn.* Ich bin Jahwe!", footnotes: ["Wird zusammen mit 4. Mose 30,3 im Neuen Testament von Jesus Christus zitiert: Matthäus 5,33."] },
      { number: 13, text: "Du sollst deinen Nächsten weder unterdrücken noch berauben. Den Lohn eines Tagelöhners darfst du nicht über Nacht bis zum nächsten Morgen behalten." },
      { number: 14, text: "Einen Tauben sollst du nicht schmähen und vor einen Blinden kein Hindernis legen. Du sollst dich vor deinem Gott fürchten, denn ich bin Jahwe!" },
      { number: 15, text: "Tut kein Unrecht im Gericht. Einen Geringen darfst du nicht bevorzugen und einen Großen nicht ehren. Du sollst ein gerechtes Urteil über deinen Nächsten sprechen." },
      { number: 16, text: "Du sollst nicht als Verleumder in deiner Sippe umhergehen. Trete nicht gegen das Leben deines Nächsten auf. Ich bin Jahwe!" },
      { number: 17, text: "Du sollst im Herzen keinen Hass gegen deinen Bruder tragen. Weise deinen Nächsten ernstlich zurecht, damit du nicht seinetwegen Schuld auf dich lädst." },
      { number: 18, text: "Räche dich nicht selbst und trage deinen Volksgenossen nichts nach. Deinen Nächsten sollst du lieben wie dich selbst.* Ich bin Jahwe!", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Matthäus 19,19; 22,39; Markus 12,31, ebenso von Paulus: Galater 5,14, und Jakobus: Jakobus 2,8."] },
      { number: 19, text: "Ihr sollt euch an meine Ordnungen halten. Kreuzt nicht Tiere verschiedener Art miteinander. Besät eure Felder nicht mit zweierlei Samen. Tragt keine Gewänder aus zweierlei Stoff." },
      { number: 20, text: "Wenn ein Mann mit einer Sklavin schläft, die für einen anderen Mann bestimmt ist, aber noch nicht losgekauft oder freigelassen wurde, muss er Schadenersatz leisten. Die beiden müssen nicht getötet werden, denn die Frau ist nicht frei gewesen." },
      { number: 21, text: "Der Mann muss Jahwe einen Schafbock als Schuldopfer an den Eingang zum Zelt der Gottesbegegnung bringen." },
      { number: 22, text: "Der Priester soll ihm damit vor Jahwe Sühne für die begangene Sünde erwirken. Dann wird ihm vergeben werden." },
      { number: 23, text: "Wenn ihr in das Land kommt und Fruchtbäume pflanzt, dann sollt ihr die Früchte wie eine Vorhaut unbeschnitten lassen. Drei Jahre lang sollen sie euch als unbeschnitten gelten. Sie dürfen nicht gegessen werden." },
      { number: 24, text: "Im vierten Jahr sollt ihr sie Jahwe als Festgabe weihen." },
      { number: 25, text: "Vom fünften Jahr an dürft ihr die Früchte der Fruchtbäume genießen. So wird ihr Ertrag umso größer sein. Ich bin Jahwe, euer Gott!" },
      { number: 26, text: "Ihr dürft nichts Blutiges essen. Treibt keine Wahrsagerei und deutet keine Zeichen." },
      { number: 27, text: "Rasiert euch das Haar nicht rings um den Kopf ab, stutzt auch nicht eure Bärte" },
      { number: 28, text: "und macht euch keine Einschnitte am Körper wegen eines Toten. Ihr sollt euch auch keine Zeichen eintätowieren. Ich bin Jahwe!" },
      { number: 29, text: "Entehre deine Tochter nicht und treibe sie nicht zur Prostitution, damit das Land nicht sexueller Unmoral verfällt und voller Schandtaten ist." },
      { number: 30, text: "Meine Sabbate sollt ihr halten und mein Heiligtum fürchten. Ich bin Jahwe!" },
      { number: 31, text: "Wendet euch nicht an Totengeister und sucht keine Wahrsager auf. Denn durch sie verunreinigt ihr euch. Ich bin Jahwe, euer Gott!" },
      { number: 32, text: "Vor grauem Haar stehe auf und begegne alten Menschen mit Respekt. Fürchte dich vor deinem Gott. Ich bin Jahwe!" },
      { number: 33, text: "Wenn ein Fremder mit euch zusammen in eurem Land lebt, dürft ihr ihn nicht unterdrücken." },
      { number: 34, text: "Wie ein Einheimischer soll er euch gelten. Du sollst ihn lieben wie dich selbst, denn ihr seid selber Fremde in Ägypten gewesen. Ich bin Jahwe, euer Gott!" },
      { number: 35, text: "Ihr sollt niemand Unrecht zufügen im Gericht, beim Messen, beim Wiegen und Abmessen." },
      { number: 36, text: "Eure Waage muss stimmen, die Gewichte und die Hohlmaße* müssen dem Grundmaß entsprechen. Ich bin Jahwe, euer Gott, der euch aus Ägypten herausgeführt hat!", footnotes: ["Hohlmaße. Wörtlich:Efa und Hin, die Grundmaße für Getreide und Flüssigkeiten."] },
      { number: 37, text: "Ihr sollt auf alle meine Ordnungen und Vorschriften achten und euch danach richten. Ich bin Jahwe, euer Gott!\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Jahwe sagte dann zu Mose:", heading: "Strafe für schwere Vergehen" },
      { number: 2, text: "\"Gib den Israeliten Folgendes weiter: Wenn ein Israelit oder ein Fremder, der in Israel lebt, eins von seinen Kindern dem Moloch opfert, muss er getötet werden. Das Volk des Landes soll ihn steinigen." },
      { number: 3, text: "Ich werde mich gegen diesen Mann wenden und ihn aus seinem Volk beseitigen, denn er hat eins von seinen Kindern dem Moloch gegeben, mein Heiligtum unrein gemacht und meinen heiligen Namen entweiht." },
      { number: 4, text: "Und wenn das Volk des Landes die Augen vor diesem Mann verschließt, der einen seiner Nachkommen dem Moloch opferte, wenn es ihn nicht tötet," },
      { number: 5, text: "dann werde ich selbst mich gegen diesen Mann und seine Sippe wenden und gegen alle, die es ihm nachmachen und sich mit dem Moloch einlassen. Ich werde sie aus ihrem Volk beseitigen." },
      { number: 6, text: "Ich werde mich auch gegen jede Person stellen, die sich mit Totengeistern oder Wahrsagern einlässt, und sie aus ihrem Volk beseitigen." },
      { number: 7, text: "So sondert euch von alldem ab und lebt heilig, denn ich bin Jahwe, euer Gott!" },
      { number: 8, text: "Ihr sollt euch nach meinen Ordnungen richten! Ich bin Jahwe, der euch heiligt!" },
      { number: 9, text: "Jeder, der seinen Vater oder seine Mutter verflucht, muss getötet werden. Die Blutschuld dafür lastet auf ihm selbst." },
      { number: 10, text: "Wenn jemand mit der Frau eines anderen Ehebruch begeht, müssen beide getötet werden: der Ehebrecher und die Ehebrecherin." },
      { number: 11, text: "Und wenn jemand mit einer der Frauen seines Vaters schläft, hat er die Scham seines Vaters entblößt. Beide müssen getötet werden. Die Blutschuld dafür lastet auf ihnen." },
      { number: 12, text: "Wenn jemand mit seiner Schwiegertochter schläft, müssen beide getötet werden. Sie haben sich auf schändliche Weise befleckt. Die Blutschuld dafür lastet auf ihnen." },
      { number: 13, text: "Wenn ein Mann mit einem anderen Mann* Geschlechtsverkehr hat, haben sich beide auf abscheuliche Weise vergangen. Sie müssen getötet werden. Die Blutschuld dafür lastet auf ihnen.", footnotes: ["Mann. Wörtlich: männlichen. Gemeint ist ein Mensch männlichen Geschlechts, gleich welchen Alters."] },
      { number: 14, text: "Wenn ein Mann eine Frau und ihre Mutter heiratet, ist das ein schändliches Vergehen. Man soll ihn und beide Frauen verbrennen. Etwas so Schändliches darf es bei euch nicht geben." },
      { number: 15, text: "Wenn ein Mann mit einem Vieh geschlechtlich verkehrt, muss er getötet werden. Auch das Tier müsst ihr umbringen." },
      { number: 16, text: "Wenn eine Frau sich irgendeinem Stück Vieh nähert, um mit ihm geschlechtlich zu verkehren, müsst ihr die Frau und das Tier umbringen. Sie müssen unbedingt getötet werden. Die Blutschuld für ihren Tod lastet auf ihnen selbst." },
      { number: 17, text: "Wenn ein Mann seine Schwester nimmt, eine Tochter seines Vaters oder seiner Mutter, und ihre Scham sieht, und sie sieht seine Scham, dann ist das eine Schandtat. Beide sollen vor dem versammelten Volk getötet werden. Der Mann hat die Scham seiner Schwester aufgedeckt. Die Blutschuld dafür lastet auf ihm." },
      { number: 18, text: "Wenn ein Mann mit einer menstruierenden Frau schläft und so ihre Scham entblößt, hat er ihre Quelle entblößt, und sie hat die Quelle ihres Blutes aufgedeckt. Beide müssen von ihrem Volk beseitigt werden." },
      { number: 19, text: "Auch die Scham der Schwester deiner Mutter oder der Schwester deines Vaters darfst du nicht aufdecken. Denn wer das tut, hat seine Blutsverwandte entblößt. Beide müssen ihre Schuld tragen." },
      { number: 20, text: "Wenn ein Mann mit der Frau seines Onkels schläft, hat er die Scham seines Onkels entblößt. Die beiden müssen ihre Sünde tragen und sollen kinderlos sterben." },
      { number: 21, text: "Wenn jemand mit der Frau seines Bruders schläft, ist das eine Befleckung. Er hat die Scham seines Bruders entblößt. Sie werden kinderlos bleiben." },
      { number: 22, text: "Haltet euch an meine Ordnungen und lebt nach meinen Geboten, damit euch das Land, in das ich euch bringen will, nicht ausspuckt." },
      { number: 23, text: "Ihr sollt die Sitten der Leute, die ich vor euch vertreibe, nicht annehmen. Denn sie haben all diese Dinge getan und ekelten mich damit an." },
      { number: 24, text: "Deshalb habe ich zu euch gesagt: 'Ihr sollt ihr Land in Besitz nehmen, euch werde ich das Land geben, das von Milch und Honig überfließt.' Ich bin Jahwe, euer Gott! Ich habe euch zu einem besonderen Volk gemacht." },
      { number: 25, text: "Ihr sollt zwischen reinen und unreinen Tieren unterscheiden, zwischen unreinen und reinen Vögeln, und euch selbst nicht zum Abscheu machen durch das Vieh, die Vögel und das, was sich auf dem Erdboden regt, was von mir für unrein erklärt wurde." },
      { number: 26, text: "Ihr sollt heilig für mich sein, denn ich, Jahwe, bin heilig. Ich habe euch von den Völkern unterschieden, dass ihr mir gehört." },
      { number: 27, text: "Und wenn in einem Mann oder einer Frau ein Toten- oder Wahrsagegeist ist, müssen sie getötet werden. Man soll sie steinigen. Die Blutschuld dafür lastet auf ihnen.\"" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Jahwe sagte zu Mose: Gib den Priestern, den Nachkommen Aarons, Folgendes weiter: \"Kein Priester darf sich verunreinigen, indem er einen Toten aus seinem Volk berührt.", heading: "Anweisungen für Priester" },
      { number: 2, text: "Ausgenommen davon sind nur seine Mutter und sein Vater, sein Sohn und seine Tochter, sein Bruder" },
      { number: 3, text: "und seine unverheiratete Schwester, wenn sie in seinem Haushalt lebt." },
      { number: 4, text: "Als Herr unter seinen Volksleuten darf er sich nicht unrein machen. Er würde dadurch entweiht." },
      { number: 5, text: "Priester dürfen sich weder den Kopf kahl scheren noch den Bart stutzen oder Einschnitte am Körper machen." },
      { number: 6, text: "Sie sollen ihrem Gott geheiligt sein und den Namen ihres Gottes nicht entweihen. Denn sie bringen die Feueropfer Jahwes dar, die Speise ihres Gottes, und müssen deshalb heilig sein." },
      { number: 7, text: "Sie dürfen keine Prostituierte oder Vergewaltigte heiraten, auch keine von ihrem Mann verstoßene Frau, denn ein Priester ist seinem Gott geweiht." },
      { number: 8, text: "Du sollst ihn als Gott geweiht ansehen, denn er bringt die Opferspeise deines Gottes dar. Er soll heilig für dich sein, denn ich bin heilig, ich bin Jahwe, der euch für sich geheiligt hat." },
      { number: 9, text: "Wenn die Tochter eines Priesters sich prostituiert, entweiht sie dadurch nicht nur sich selbst, sondern auch ihren Vater. Sie muss verbrannt werden." },
      { number: 10, text: "Der Hohe Priester, auf dessen Kopf das Salböl gegossen wurde und den man bei seiner Einsetzung mit den entsprechenden Gewändern bekleidet hat, darf auch bei einem Trauerfall* sein Haupthaar nicht ungepflegt herunterhängen lassen und seine Kleidung zerreißen.", footnotes: ["auch bei einem Trauerfall. Zusatz des Übersetzers zur Verdeutlichung."] },
      { number: 11, text: "Er darf zu keinem Leichnam gehen, auch wenn es sein Vater oder seine Mutter ist, damit er sich nicht verunreinigt." },
      { number: 12, text: "In diesem Fall* soll er das Heiligtum nicht verlassen, denn sonst würde er das Heiligtum seines Gottes entweihen. Die Weihe des Salböls Gottes ist ja auf ihm. Ich bin Jahwe!", footnotes: ["In diesem Fall. Gemeint ist offenbar der Fall, dass der Leichnam seines Vaters oder seiner Mutter in seinem Haus aufgebahrt ist."] },
      { number: 13, text: "Er darf nur eine Frau heiraten, die noch unberührt ist." },
      { number: 14, text: "Eine Witwe, eine Verstoßene, eine Vergewaltigte oder eine Prostituierte darf er nicht zur Frau nehmen. Es muss eine unberührte junge Frau aus seinem eigenen Volk sein." },
      { number: 15, text: "Sonst würde er seine Nachkommen unter seinem Volk entweihen. Denn ich bin Jahwe, der ihn heiligt!\"" },
      { number: 16, text: "Jahwe sagte zu Mose:" },
      { number: 17, text: "\"Gib Aaron Folgendes weiter: Sollte einer deiner künftigen Nachkommen mit einem Gebrechen behaftet sein, darf er nicht zum Altar kommen, um die Speise seines Gottes zu opfern." },
      { number: 18, text: "Denn keiner, der ein Gebrechen hat, darf in meine Nähe kommen: kein Blinder oder Lahmer, keiner, der eine Scharte hat oder missgebildet ist," },
      { number: 19, text: "keiner, der Arm oder Bein gebrochen hat," },
      { number: 20, text: "kein Buckliger oder Kleinwüchsiger, keiner, der eine Augen- oder Hautkrankheit hat, auch keiner mit zerquetschten Hoden." },
      { number: 21, text: "Von den Nachkommen des Priesters Aaron darf keiner, der ein Gebrechen hat, herantreten, um die Feueropfer Jahwes darzubringen. Er hat ein Gebrechen und soll nicht herantreten, um die Speise seines Gottes zu opfern." },
      { number: 22, text: "Doch von den Opfern, die seinem Gott gebracht werden, darf er essen, sowohl vom Heiligen, als auch dem Höchstheiligen." },
      { number: 23, text: "Aber weil er ein Gebrechen hat, darf er nicht zum Vorhang kommen und sich auch dem Altar nicht nähern, damit er meine heiligen Dinge nicht entweiht. Denn ich bin Jahwe, der sie heiligt!\"" },
      { number: 24, text: "Mose sagte dies Aaron und allen Israeliten." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Anweisungen für den Genuss von Opfergaben" },
      { number: 2, text: "\"Sag Aaron und seinen Söhnen, dass sie achtsam mit den heiligen Gaben umgehen, welche die Israeliten mir aussondern, dass sie meinen heiligen Namen nicht entweihen. Ich bin Jahwe!" },
      { number: 3, text: "Sag zu ihnen: Wenn jemand von euch oder euren Nachkommen sich im Zustand der Unreinheit diesen heiligen Gaben nähert, die die Israeliten für Jahwe aussondern, muss diese Person beseitigt und aus meiner Gegenwart weggeschafft werden. Ich bin Jahwe!" },
      { number: 4, text: "Wer von den Nachkommen Aarons Aussatz hat oder an Ausfluss leidet, darf nicht von den heiligen Gaben essen, bis er wieder rein ist. Und wenn jemand irgendetwas berührt, das durch einen Toten unrein wurde, oder wer einen Samenerguss hatte" },
      { number: 5, text: "oder wer Kleingetier berührt, das für ihn unrein ist, oder einen Menschen, der durch irgendeinen Grund für ihn unrein ist," },
      { number: 6, text: "wer so etwas berührt, wird bis zum Abend unrein sein. Er darf nicht von den heiligen Gaben essen, sondern soll seinen Körper mit Wasser übergießen." },
      { number: 7, text: "Erst wenn die Sonne untergegangen ist, ist er wieder rein. Dann darf er von den heiligen Gaben essen, es ist ja seine Speise." },
      { number: 8, text: "Er darf kein verendetes oder zerrissenes Tier essen, denn daran wird er unrein. Ich bin Jahwe!" },
      { number: 9, text: "So sollen sie meine Anweisungen befolgen, damit sie deswegen keine Schuld auf sich laden und sterben müssen, weil sie das Geheiligte entweihen. Ich bin Jahwe, der sie heiligt!" },
      { number: 10, text: "Kein Unbefugter darf etwas Heiliges essen, auch nicht, wenn er bei einem Priester wohnt oder für Lohn bei ihm arbeitet." },
      { number: 11, text: "Wenn der Priester aber jemand für Geld kauft, dann darf diese Person davon essen, ebenfalls der im Haus geborene Sklave." },
      { number: 12, text: "Wenn die Tochter eines Priesters einen Mann heiratet, der kein Priester ist, darf sie nicht von den heiligen Gaben essen." },
      { number: 13, text: "Wenn sie aber als Witwe oder Verstoßene in ihr Vaterhaus zurückkehrt und keine Kinder hat, darf sie wie früher von der Speise ihres Vaters essen. Aber kein Unbefugter darf davon essen." },
      { number: 14, text: "Wenn jemand aus Versehen etwas Heiliges isst, muss er ein Fünftel hinzufügen und das Heilige dem Priester erstatten." },
      { number: 15, text: "Die Priester dürfen die heiligen Gaben nicht entweihen, die die Israeliten Jahwe bringen." },
      { number: 16, text: "Wenn sie andere Israeliten davon essen lassen, würden sie ihnen eine schwere Schuld aufladen. Denn ich bin Jahwe, der sie heiligt!\"" },
      { number: 17, text: "Jahwe sagte zu Mose:", heading: "Die Tauglichkeit der Opfertiere" },
      { number: 18, text: "\"Gib Aaron, seinen Söhnen und allen Israeliten Folgendes weiter: Wenn ein Israelit oder ein Fremder, der in Israel lebt, Jahwe ein Brandopfer bringt, ob es nach einem Gelübde ist oder eine freiwillige Gabe," },
      { number: 19, text: "dann muss es ein fehlerfreies männliches Tier von den Rindern, Schafen oder Ziegen sein, damit ihr Wohlwollen bei Gott findet." },
      { number: 20, text: "Alles, was einen Fehler hat, dürft ihr nicht bringen, denn es wird euch nicht wohlgefällig machen." },
      { number: 21, text: "Auch wenn jemand Jahwe ein Freudenopfer bringt, um ein Gelübde zu erfüllen oder wenn er ihm eine freiwillige Gabe vom Rind oder vom Kleinvieh bringt, muss das Tier ohne Fehler sein, damit ihr Wohlwollen findet. Es darf kein Makel daran sein." },
      { number: 22, text: "Ein blindes, verletztes oder verstümmeltes Tier dürft ihr Jahwe nicht bringen, auch dann nicht, wenn es Warzen, die Krätze oder eine Flechte hat. Nichts davon darf auf Jahwes Altar kommen." },
      { number: 23, text: "Einen Stier oder ein Schaf, das missgebildet oder verkümmert ist, kannst du als freiwillige Gabe opfern. Zur Erfüllung eines Gelübdes aber wird es kein Gefallen finden." },
      { number: 24, text: "Ein Tier, dessen Hoden zerquetscht, zerstoßen, abgerissen oder abgeschnitten sind, dürft ihr Jahwe nicht bringen. Ihr dürft in eurem Land kein Tier kastrieren." },
      { number: 25, text: "Selbst wenn solche Tiere aus dem Besitz eines Ausländers stammen, dürft ihr sie eurem Gott nicht als Speise darbringen. Sie haben einen Schaden, ein Makel, und werden euch kein Wohlwollen bringen.\"" },
      { number: 26, text: "Jahwe sagte zu Mose:" },
      { number: 27, text: "\"Wenn ein Stierkalb, ein Schaf- oder Ziegenlamm geboren wird, muss es sieben Tage bei seinem Muttertier bleiben. Erst vom achten Tag an findet es als Feueropfer Jahwes Gefallen." },
      { number: 28, text: "Ihr dürft auch nicht das Muttertier am gleichen Tag wie sein Junges schlachten." },
      { number: 29, text: "Wenn ihr Jahwe ein Dankopfer schlachtet, sollt ihr es so tun, dass ihr Wohlwollen findet." },
      { number: 30, text: "Es muss noch am selben Tag gegessen werden. Ihr dürft nichts davon bis zum Morgen übriglassen. Ich bin Jahwe!" },
      { number: 31, text: "Beachtet und befolgt meine Gebote! Ich bin Jahwe!" },
      { number: 32, text: "Entweiht meinen heiligen Namen nicht, damit ich unter den Israeliten heilig gehalten werde. Ich bin Jahwe, der euch heiligt" },
      { number: 33, text: "und euch aus Ägypten geführt hat, um euer Gott zu sein. Ich bin Jahwe!\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die nationale Heiligung (23-27)" },
      { number: 2, text: "\"Gib den Israeliten weiter: Die Feste Jahwes, meine Feste, die ihr als heilige Versammlungen ausrufen sollt, sind die Folgenden:" },
      { number: 3, text: "Sechs Tage darf man eine Arbeit tun, aber am siebten Tag ist Sabbat, ein Feiertag, eine heilige Versammlung. Da dürft ihr keinerlei Arbeit tun. Es ist ein Sabbat für Jahwe, wo immer ihr wohnt.", heading: "Der Sabbat" },
      { number: 4, text: "Folgende Feste Jahwes sind heilige Versammlungen, die ihr zu bestimmten Zeiten ausrufen sollt:", heading: "Passa- und Mazzenfest" },
      { number: 5, text: "Das Passa* Jahwes beginnt am späten Nachmittag* des 14. April*.", footnotes: ["Passa. Siehe 2. Mose 12-13.", "Am späten Nachmittag. Wörtlich: Zwischen den zwei Abenden. Gemeint ist wahrscheinlich die Zeit zwischen Niedergang (15 Uhr) und Untergang der Sonne.", "April. Wörtlich: des 1. Monats."] },
      { number: 6, text: "Am darauffolgenden Tag beginnt das Mazzenfest Jahwes, an dem ihr sieben Tage lang Mazzen, ungesäuertes Brot, essen sollt." },
      { number: 7, text: "Am ersten Tag sollt ihr eine heilige Versammlung abhalten und dürft keinerlei Arbeit verrichten." },
      { number: 8, text: "Und an jedem der sieben Tage sollt ihr Jahwe ein Feueropfer bringen. Am siebten Tag sollt ihr wieder eine heilige Versammlung abhalten und dürft keinerlei Arbeit verrichten.\"" },
      { number: 9, text: "Jahwe sagte zu Mose:", heading: "Das Fest der Ersten Garbe" },
      { number: 10, text: "\"Gib den Israeliten Folgendes weiter: Wenn ihr in dem Land, das ich euch gebe, die Ernte einbringt, sollt ihr die erste Garbe eurer Ernte dem Priester bringen." },
      { number: 11, text: "Dieser soll sie am Tag nach dem Sabbat vor Jahwe hin- und herschwingen, damit ihr sein Wohlwollen erlangt." },
      { number: 12, text: "An dem Tag, an dem ihr die Garbe hin- und herschwingen lasst, sollt ihr ein fehlerfreies einjähriges Lamm als Brandopfer zu Jahwe bringen," },
      { number: 13, text: "dazu als Speisopfer vier Liter Feinmehl mit Ölivenöl vermengt, beides als Feueropfer für Jahwe, damit der Geruch ihn befriedigt. Als Trankopfer bringt einen Liter Wein." },
      { number: 14, text: "Bis zu dem Tag, an dem ihr Gott diese Gaben gebracht habt, dürft ihr von der neuen Ernte weder Brot noch geröstete Körner noch Jungkorn essen. Das gilt für alle Zukunft und überall, wo ihr wohnt." },
      { number: 15, text: "Vom Tag nach dem Sabbat, an dem ihr die Garbe für das Schwingopfer gebracht habt, sollt ihr sieben volle Wochen zählen.", heading: "Das Wochenfest (Pfingsten)" },
      { number: 16, text: "Bis zum Tag nach dem siebten Sabbat sollen es fünfzig Tage sein. Dann sollt ihr Jahwe ein Speisopfer von der neuen Ernte bringen." },
      { number: 17, text: "Von euren Wohnstätten bringt Jahwe zwei geweihte Brote als Erstlinge. Sie sollen aus vier Litern Feinmehl mit Sauerteig gebacken sein." },
      { number: 18, text: "Außer dem Brot sollt ihr Jahwe sieben fehlerlose einjährige Lämmer, einen jungen Stier und zwei Schafböcke als Brandopfer bringen, dazu die vorgeschriebenen Speis- und Trankopfer. So ist es ein Feueropfer, dessen Geruch Jahwe befriedigt." },
      { number: 19, text: "Als Sündopfer sollt ihr einen Ziegenbock bringen und als Freudenopfer zwei einjährige Lämmer." },
      { number: 20, text: "Der Priester soll die beiden Lämmer zusammen mit dem Erstlingsbrot vor Jahwe hin- und herschwingen. Sie sind Jahwe geweiht und fallen dem Priester zu." },
      { number: 21, text: "An diesem Tag sollt ihr eine heilige Versammlung ausrufen und dürft keinerlei Arbeit verrichten. Diese Weisung gilt für alle Zeiten und an allen euren Wohnorten." },
      { number: 22, text: "Und wenn ihr die Ernte eures Landes einbringt, sollst du das Feld nicht bis an den Rand abernten. Du sollst auch keine Nachlese halten. Lass es für die Armen und Fremden übrig. Ich bin Jahwe, euer Gott!\"" },
      { number: 23, text: "Jahwe sagte zu Mose:", heading: "Der Neujahrstag" },
      { number: 24, text: "\"Gib den Israeliten Folgendes weiter: Der 1. Oktober* soll ein Ruhetag für euch sein, eine heilige Versammlung, in Erinnerung gerufen durch Hörnerschall.", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
      { number: 25, text: "Ihr dürft keinerlei Arbeit verrichten und sollt Jahwe ein Feueropfer darbringen.\"" },
      { number: 26, text: "Jahwe sagte Mose noch Folgendes:", heading: "Der Versöhnungstag" },
      { number: 27, text: "\"Doch am 10. dieses Monats ist der Versöhnungstag. Da sollt ihr eine heilige Versammlung abhalten, euch demütigen und Jahwe ein Feueropfer bringen." },
      { number: 28, text: "Ihr dürft an diesem Tag keinerlei Arbeit verrichten, denn es ist der Versöhnungstag, an dem für euch vor Jahwe, eurem Gott, Sühne erwirkt wird." },
      { number: 29, text: "Denn jede Person, die sich an diesem Tag nicht demütigt, soll vom Volk beseitigt werden.*", footnotes: ["Wird im Neuen Testament von Petrus zitiert: Apostelgeschichte 3,23."] },
      { number: 30, text: "Und jede Person, die an diesem Tag irgendeine Arbeit tut, werde ich aus ihrem Volk beseitigen." },
      { number: 31, text: "Ihr dürft am Versöhnungstag keinerlei Arbeit verrichten. Das gilt für alle Zukunft und überall, wo ihr wohnt." },
      { number: 32, text: "Es soll ein Sabbat, ein Feiertag, für euch sein und ihr sollt euch demütigen. Diese Feiertagsruhe soll schon am Abend vorher beginnen, also am 9. des Monats, und bis zum nächsten Abend dauern.\"" },
      { number: 33, text: "Jahwe sagte zu Mose:", heading: "Das Laubhüttenfest" },
      { number: 34, text: "\"Gib den Israeliten Folgendes weiter: Am 15. Oktober* beginnt das siebentägige Laubhüttenfest für Jahwe.", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
      { number: 35, text: "Am ersten Tag soll eine heilige Versammlung sein. Ihr dürft keinerlei Arbeit verrichten." },
      { number: 36, text: "Sieben Tage lang sollt ihr Jahwe täglich Feueropfer bringen. Am achten Tag soll wieder eine heilige Versammlung stattfinden, eine Festversammlung. Ihr sollt Jahwe ein Feueropfer bringen und dürft keinerlei Arbeit verrichten." },
      { number: 37, text: "Das sind die Festzeiten Jahwes, die ihr als heilige Versammlungen ausrufen sollt, um Jahwe Feueropfer zu bringen: Brandopfer und Speisopfer, Schlachtopfer und Trankopfer, jedes an seinem Tag." },
      { number: 38, text: "Die Sabbate Jahwes und die anderen Gaben, sowie die Opfer, die ihr Jahwe durch ein Gelübde zugesagt oder ihm freiwillig gebracht habt, bleiben davon unberührt." },
      { number: 39, text: "Nachdem ihr die Ernte eingebracht habt, sollt ihr sieben Tage lang, vom 15. Oktober an, das Fest Jahwes feiern. Der erste und der achte Tag soll ein Ruhetag sein." },
      { number: 40, text: "Am ersten Tag sollt ihr euch die schönsten Baumfrüchte nehmen, Palmwedel und Zweige von Laubbäumen und Bachweiden und sollt euch sieben Tage lang vor Jahwe, eurem Gott, freuen." },
      { number: 41, text: "Jedes Jahr sollt ihr dieses Fest im Oktober sieben Tage lang für Jahwe feiern. Das ist eine immerwährende Ordnung für alle Generationen." },
      { number: 42, text: "Während dieser sieben Tage sollen alle Einheimischen in Israel in Laubhütten wohnen," },
      { number: 43, text: "damit eure Nachkommen wissen, dass ich die Israeliten in Laubhütten wohnen ließ, als ich sie aus Ägypten herausführte. Ich bin Jahwe, euer Gott!\"" },
      { number: 44, text: "So verkündete Mose den Israeliten die Festzeiten Jahwes." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Leuchter und Schaubrote" },
      { number: 2, text: "\"Befiehl den Israeliten, dir reines Öl aus zerstoßenen Oliven zu bringen, damit man einen Leuchter aufstellen kann, dessen Lampen ständig brennen." },
      { number: 3, text: "Aaron soll diesen Leuchter im Zelt der Gottesbegegnung vor dem Vorhang zur Lade mit dem Bundesgesetz aufstellen und dafür sorgen, dass seine Lampen ständig vor Jahwe brennen, vom Abend bis zum Morgen. Diese Anordnung gilt für alle Zukunft." },
      { number: 4, text: "Auf dem reinen Leuchter soll er die Lampen herrichten, dass sie ständig vor Jahwe sind." },
      { number: 5, text: "Dann sollst du aus je vier Litern Feinmehl zwölf Lochbrote* backen", footnotes: ["Lochbrot. Ein runder Brotlaib, der in der Mitte durchstoßen ist. Hier ist eher an ein großes Ringbrot zu denken."] },
      { number: 6, text: "und sie auf dem reinen Tisch vor Jahwe in zwei Stapeln aufschichten, sechs auf jedem Stapel." },
      { number: 7, text: "Auf jeden Stapel sollst du reinen Weihrauch legen, der dann vom Brot als der zu verbrennende Teil genommen wird. So wird es ein Feueropfer für Jahwe." },
      { number: 8, text: "An jedem Sabbat soll Aaron die Brote immer wieder neu vor Jahwe auflegen, als ewige Bundesverpflichtung der Israeliten." },
      { number: 9, text: "Das Brot soll Aaron und seinen Nachkommen gehören. Für alle Zukunft steht ihnen das zu. Es muss aber an heiliger Stätte gegessen werden, denn es ist ein höchst heiliger Teil von den Feueropfern Jahwes.\"" },
      { number: 10, text: "Der Sohn einer Israelitin und eines Ägypters ging unter die Israeliten und geriet im Lager mit einem israelitischen Mann in Streit.", heading: "Gotteslästerung, Totschlag und Körperverletzung" },
      { number: 11, text: "Dabei lästerte der Sohn der Israelitin den Namen Gottes und verfluchte ihn. Seine Mutter war Schelomit, eine Tochter Dibris aus dem Stamm Dan. Man brachte den Mann zu Mose." },
      { number: 12, text: "Der ließ ihn einsperren, bis Jahwe eine Weisung für diesen Fall geben würde." },
      { number: 13, text: "Jahwe sagte Mose:" },
      { number: 14, text: "\"Bring den Flucher aus dem Lager hinaus! Dort sollen alle, die seine Lästerung gehört haben, ihre Hände auf seinen Kopf stützen, und die ganze Gemeinschaft muss ihn steinigen." },
      { number: 15, text: "Zu den Israeliten aber sollst du sagen: 'Jeder, der seinen Gott verflucht, muss seine Schuld tragen." },
      { number: 16, text: "Wer den Namen Jahwes lästert, muss getötet werden. Die ganze Gemeinschaft soll ihn steinigen. Das gilt für die Fremden unter euch genauso wie für die Einheimischen: Wer den Namen lästert, muss getötet werden." },
      { number: 17, text: "Wenn jemand einen Menschen erschlägt, muss er getötet werden." },
      { number: 18, text: "Wer ein Stück Vieh totschlägt, muss es erstatten, Leben für Leben." },
      { number: 19, text: "Wenn jemand seinem Nächsten einen Schaden zufügt, soll man ihm antun, was er getan hat." },
      { number: 20, text: "Knochenbruch für Knochenbruch, Auge für Auge, Zahn für Zahn.* Der Schaden, den er einem Menschen zufügt, soll ihm zugefügt werden.", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Matthäus 5,38."] },
      { number: 21, text: "Wer ein Stück Vieh totschlägt, soll es erstatten, wer aber einen Menschen totschlägt, soll selbst getötet werden." },
      { number: 22, text: "Ein und dasselbe Recht gilt für euch alle, für den Fremden wie für den Einheimischen. Denn ich bin Jahwe, euer Gott!'\"" },
      { number: 23, text: "Mose sagte dies alles den Israeliten. Da brachten sie den Flucher aus dem Lager hinaus und steinigten ihn. Die Israeliten machten alles so, wie Jahwe es Mose befohlen hatte." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Auf dem Berg Sinai sagte Jahwe zu Mose:", heading: "Das Sabbatjahr" },
      { number: 2, text: "\"Gib den Leuten von Israel Folgendes weiter: Wenn ihr in das Land kommt, das ich euch gebe, soll das Land einen Sabbat für Jahwe feiern." },
      { number: 3, text: "Sechs Jahre sollst du dein Feld bestellen und deinen Weinberg beschneiden und ihre Erträge einbringen." },
      { number: 4, text: "Aber im siebten Jahr soll das Land einen Sabbat haben, ein Ruhejahr, einen Sabbat für Jahwe. Dann sollst du dein Feld nicht bestellen und deinen Weinberg nicht beschneiden." },
      { number: 5, text: "Was nach deiner Ernte wächst, sollst du nicht einsammeln, und die Trauben deines unbeschnittenen Weinstocks sollst du nicht abschneiden. Es soll ein Sabbatjahr sein für das Land." },
      { number: 6, text: "Was das Land aber während des Sabbats hervorbringt, soll euch und allen, die bei euch leben, zur Nahrung dienen, deinen Sklaven und Sklavinnen, deinen Tagelöhnern und Gastarbeitern." },
      { number: 7, text: "Auch deinem Vieh und dem Wild in deinem Land soll sein Ertrag zur Speise dienen.\"" },
      { number: 8, text: "\"Zähl dir sieben Sabbatjahre ab, also sieben mal sieben Jahre, sodass insgesamt 49 Jahre vergangen sind.", heading: "Das Jubeljahr" },
      { number: 9, text: "Dann sollst du am 10. Oktober* den Schofar*, das Signalhorn, blasen. Am Versöhnungstag sollt ihr den Schofar im ganzen Land erschallen lassen.", footnotes: ["Oktober. Wörtlich: im 7. Monat.", "Der Schofar war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 10, text: "Dieses 50. Jahr sollt ihr für heilig erklären und überall im Land eine Freilassung für seine Bewohner ausrufen. Es soll ein Jubeljahr* für euch sein, denn jeder wird wieder zu seinem Eigentum kommen und jeder soll zu seiner Sippe zurückkehren.", footnotes: ["Jubeljahr. Hebräisch: jobel = Horn eines Schafbocks. Das deutsche Wort Jubel ist davon abgeleitet. Durch das Blasen dieser Signalhörner, die Schofar hießen, wurde das Jubeljahr eingeleitet."] },
      { number: 11, text: "Das 50. Jahr soll ein Jubeljahr für euch sein. Ihr sollt nicht säen und, was nachwächst, nicht ernten, und die Trauben der unbeschnittenen Weinstöcke nicht lesen." },
      { number: 12, text: "Denn es ist ein Jubeljahr: Es soll euch heilig sein. Nur was das Feld von selber trägt, sollt ihr essen." },
      { number: 13, text: "In diesem Jubeljahr soll jeder wieder zu seinem Eigentum kommen." },
      { number: 14, text: "Das müsst ihr unbedingt beachten, wenn ihr eurem Nächsten etwas verkauft oder etwas von ihm kauft." },
      { number: 15, text: "Der Preis soll sich nach der Zahl der Jahre richten, die seit dem Jubeljahr vergangen sind. Nach der Zahl der Jahre, die es dir Ertrag bringt, soll er es dir verkaufen." },
      { number: 16, text: "Je mehr Jahre es noch sind, desto höher soll der Kaufpreis sein, und je weniger Jahre, desto niedriger soll der Kaufpreis sein. Denn er verkauft dir eine Anzahl von Jahreserträgen." },
      { number: 17, text: "Niemand soll seinen Nächsten übervorteilen. Fürchte dich vor deinem Gott, denn ich bin Jahwe, euer Gott!" },
      { number: 18, text: "Haltet euch an meine Ordnungen und richtet euch nach meinen Geboten! Dann werdet ihr ruhig und sicher in eurem Land wohnen." },
      { number: 19, text: "Das Land wird seine Frucht geben, und ihr werdet euch satt essen können und sicher wohnen." },
      { number: 20, text: "Wenn ihr aber sagt: 'Was sollen wir im 7. Jahr essen? Wir dürfen ja nicht säen und den Ertrag nicht ernten'," },
      { number: 21, text: "so werde ich im 6. Jahr meinen Segen für euch aufbieten, dass es den Ertrag von drei Jahren bringt." },
      { number: 22, text: "Wenn ihr im 8. Jahr ausgesät habt, könnt ihr noch von diesem Ertrag essen. Bis der Ertrag des 9. Jahres eingebracht ist, werdet ihr noch vom alten Getreide essen." },
      { number: 23, text: "Das Land darf nicht endgültig verkauft werden, denn das Land gehört mir. Für mich seid ihr nur wie Fremde und Gastarbeiter." },
      { number: 24, text: "Im ganzen Land sollt ihr ein Rückkaufsrecht auf Grund und Boden gewähren." },
      { number: 25, text: "Wenn dein Bruder verarmt und etwas von seinem Grundbesitz verkauft, muss sein nächster Verwandter als Löser eintreten und das Veräußerte zurückkaufen." },
      { number: 26, text: "Wenn jemand keinen Löser hat und später selbst genug zum Rückkauf aufbringt," },
      { number: 27, text: "dann soll er die Jahre seit dem Verkauf berechnen und dem Käufer den Restbetrag erstatten und so wieder zu seinem Besitz kommen." },
      { number: 28, text: "Kann er die Mittel zum Rückkauf nicht aufbringen, dann bleibt sein Besitz bis zum Jubeljahr in der Hand des Käufers und fällt dann wieder an ihn als den ursprünglichen Besitzer zurück." },
      { number: 29, text: "Wenn jemand ein Wohnhaus in einer ummauerten Stadt verkauft, bleibt sein Rückkaufsrecht vom Zeitpunkt des Verkaufs an ein volles Jahr bestehen." },
      { number: 30, text: "Kauft er es innerhalb dieser Frist nicht zurück, dann geht es unwiderruflich in den Besitz des Käufers und seiner Erben über. Auch im Jubeljahr fällt es nicht an den ursprünglichen Besitzer zurück." },
      { number: 31, text: "Doch die Häuser in Dörfern, die nicht von einer Mauer umgeben sind, werden zum freien Feld des Landes gerechnet. Für solch ein Haus besteht Rückkaufsrecht, und es fällt im Jubeljahr an den ursprünglichen Besitzer zurück." },
      { number: 32, text: "Auch in den Levitenstädten besteht ein unbefristetes Rückkaufsrecht." },
      { number: 33, text: "Einer der Leviten kann als Löser auftreten oder das Haus fällt im Jubeljahr an seinen ursprünglichen Besitzer zurück. Denn die Häuser der Leviten sind ihr Erbbesitz unter den Israeliten." },
      { number: 34, text: "Das Weideland aber, das zu ihren Städten gehört, darf nicht verkauft werden, denn es gehört ihnen als ewiger Besitz." },
      { number: 35, text: "Wenn dein Bruder neben dir verarmt und sich nicht mehr neben dir halten kann, dann sollst du ihn unterstützen. Er soll wie ein Fremder oder Gastarbeiter sein Leben bei dir fristen können." },
      { number: 36, text: "Fordere keine Zinsen von ihm, sondern fürchte dich vor deinem Gott, damit dein Bruder neben dir leben kann." },
      { number: 37, text: "Verlange keine Zinsen für dein Geld und keinen Zuschlag, wenn du ihm Nahrungsmittel leihst." },
      { number: 38, text: "Ich bin Jahwe, euer Gott, der euch aus Ägypten geführt hat, um euch das Land Kanaan zu geben und euer Gott zu sein." },
      { number: 39, text: "Wenn dein Bruder neben dir so verarmt, dass er sich selbst an dich verkauft, sollst du ihn nicht wie einen Sklaven behandeln," },
      { number: 40, text: "sondern wie einen Tagelöhner oder Gastarbeiter. Bis zum nächsten Jubeljahr soll er für dich arbeiten." },
      { number: 41, text: "Dann soll er samt seiner Familie frei werden, zu seiner Sippe zurückkehren und seinen Erbbesitz wiederbekommen." },
      { number: 42, text: "Denn es sind meine Leute, die ich aus Ägypten herausgeführt habe. Sie dürfen nicht wie Sklaven verkauft werden." },
      { number: 43, text: "Du sollst also nicht mit Gewalt über ihn herrschen, sondern dich vor deinem Gott fürchten." },
      { number: 44, text: "Wenn ihr Sklaven und Sklavinnen braucht, könnt ihr sie von euren Nachbarvölkern kaufen." },
      { number: 45, text: "Auch von den Gastarbeitern, die bei euch leben, und von deren Nachkommen, die in eurem Land geboren sind, könnt ihr Sklaven kaufen und dürft sie besitzen." },
      { number: 46, text: "Ihr dürft sie sogar euren Söhnen als dauernden Besitz vererben. Sie dürft ihr als Sklaven arbeiten lassen. Aber über eure Brüder, die Israeliten, dürft ihr nicht mit Gewalt herrschen." },
      { number: 47, text: "Wenn ein Fremder oder Gastarbeiter neben dir zu Vermögen kommt, und dein Bruder neben ihm verarmt so, dass er sich dem Fremden oder Gastarbeiter oder dem Nachkommen eines Fremden verkauft," },
      { number: 48, text: "dann soll jederzeit das Lösungsrecht für ihn bestehen. Einer seiner Brüder kann ihn freikaufen." },
      { number: 49, text: "Es kann auch sein Onkel sein, der Sohn seines Onkels oder einer seiner näheren Verwandten. Und wenn er das Geld selbst aufbringt, kann er sich selbst freikaufen." },
      { number: 50, text: "Er soll mit seinem Käufer von dem Jahr an, in dem er sich verkauft hat, bis zum nächsten Jubeljahr rechnen. Und sein Verkaufspreis soll sich nach der Zahl der Jahre richten. Den Jahressatz berechne man nach dem Lohn eines Tagelöhners." },
      { number: 51, text: "Sind es noch viele Jahre, soll er für seinen Loskauf einen entsprechenden Teil des Kaufpreises erstatten." },
      { number: 52, text: "Wenn nur noch wenige Jahre bis zum Jubeljahr übrig sind, soll man es ihm anrechnen. Seinen Dienstjahren entsprechend soll er sich loskaufen." },
      { number: 53, text: "Sein Herr soll ihn wie einen Tagelöhner behandeln. Du darfst nicht zulassen, dass er wie ein Sklave behandelt wird." },
      { number: 54, text: "Wird er nicht auf diese Weise losgekauft, sollen er und seine Kinder im Jubeljahr freigelassen werden." },
      { number: 55, text: "Denn die Israeliten sind mein Eigentum, es sind meine Leute, die ich aus Ägypten herausgeführt habe. Ich bin Jahwe, euer Gott!\"" },
    ] },
    { number: 26, verses: [
      { number: 1, text: "\"Ihr sollt euch keine nichtigen Götzen machen, euch kein Gottesbild und keine Steinsäule aufstellen, auch keine Steine mit eingemeißelten Bildern, um euch davor zur Anbetung niederzuwerfen, denn ich bin Jahwe, euer Gott.", heading: "Segen und Fluch" },
      { number: 2, text: "Ihr sollt meine Sabbate halten und mein Heiligtum fürchten. Ich bin Jahwe!" },
      { number: 3, text: "Wenn ihr nach meinen Vorschriften lebt und meine Gebote befolgt," },
      { number: 4, text: "werde ich euch den Regen schicken zur rechten Zeit, sodass euer Land seinen Ertrag gibt und die Bäume ihre Frucht." },
      { number: 5, text: "Die Dreschzeit wird sich bis zur Weinlese ausdehnen und die Weinlese bis zur Aussaat. Ihr werdet genug zu essen haben und sicher in eurem Land wohnen." },
      { number: 6, text: "Ich werde für Frieden in eurem Land sorgen, dass ihr euch niederlegen könnt und niemand euch aufschreckt. Ich werde die bösen Tiere im Land ausrotten, und kein Schwert wird durchs Land ziehen." },
      { number: 7, text: "Ihr werdet eure Feinde verfolgen. Vor euren Augen fallen sie durch das Schwert." },
      { number: 8, text: "Fünf von euch werden hundert verfolgen, und hundert von euch zehntausend. Eure Feinde fallen durch das Schwert." },
      { number: 9, text: "Ich wende mich euch zu und mache euch fruchtbar und stehe zu meinem Bund mit euch." },
      { number: 10, text: "Ihr werdet noch vom alten Getreide zu essen haben, wenn ihr Platz für das neue schaffen müsst." },
      { number: 11, text: "Ich werde meine Wohnung mitten unter euch haben und mich nicht mit Abscheu von euch wenden." },
      { number: 12, text: "Ich werde unter euch leben und euer Gott sein. Und ihr seid mein Volk.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 2. Korinther 6,16."] },
      { number: 13, text: "Ich bin Jahwe, euer Gott, der euch aus Ägypten herausgeführt hat, wo ihr Sklaven gewesen seid. Ich habe die Hölzer eures Jochs zerbrochen und euch wieder aufrecht gehen lassen." },
      { number: 14, text: "Wenn ihr mir aber nicht gehorcht und diese Gebote nicht befolgt," },
      { number: 15, text: "wenn ihr meine Vorschriften missachtet und meine Rechtsordnungen verabscheut, sodass meine Gebote unbeachtet bleiben und mein Bund gebrochen wird," },
      { number: 16, text: "dann werde ich euch Folgendes antun: Ich werde Entsetzen über euch bringen, Schwindsucht und Fieber, die euch die Augen erlöschen und die Seele verkümmern lassen. Vergeblich werdet ihr eure Saat ausbringen, denn eure Feinde werden sie verzehren." },
      { number: 17, text: "Ich werde mich gegen euch stellen und lasse eure Feinde über euch siegen. Die euch hassen, werden über euch herrschen. Ihr werdet fliehen, obwohl euch niemand verfolgt." },
      { number: 18, text: "Und wenn ihr auch dann noch nicht auf mich hört, werde ich euch noch siebenmal härter für eure Sünden bestrafen." },
      { number: 19, text: "Ich werde euren maßlosen Stolz brechen und mache euren Himmel wie Eisen und eure Erde wie Erz." },
      { number: 20, text: "Umsonst verbraucht ihr dann eure Kraft: Euer Land wird seinen Ertrag nicht geben, und die Bäume des Landes werden keine Früchte tragen." },
      { number: 21, text: "Und wenn ihr euch mir entgegenstellt und mir nicht gehorchen wollt, werde ich euch noch siebenmal härter für eure Sünden bestrafen." },
      { number: 22, text: "Dann lasse ich die Raubtiere auf euch los. Sie werden euch kinderlos machen, euer Vieh ausrotten und eure Zahl gering machen, sodass die Wege bei euch verlassen sind." },
      { number: 23, text: "Und wenn ihr euch dadurch nicht zurechtweisen lasst und euch weiter gegen mich stellt," },
      { number: 24, text: "dann werde auch ich mich gegen euch stellen und euch noch siebenmal härter für eure Sünden bestrafen." },
      { number: 25, text: "Ich werde ein Schwert über euch kommen lassen, das die Rache des Bundes vollstreckt. Zieht ihr euch dann in eure Städte zurück, schicke ich die Pest unter euch und lasse euch von Feinden belagern." },
      { number: 26, text: "Wenn ich dann euren Brotvorrat vernichte, werden zehn Frauen nur noch einen einzigen Backofen brauchen. Dann bringen sie euch das Brot abgewogen zurück. Und wenn ihr gegessen habt, seid ihr nicht satt." },
      { number: 27, text: "Wenn ihr mir dann immer noch nicht gehorcht und euch immer noch weiter gegen mich stellt," },
      { number: 28, text: "dann trete ich im Zorn gegen euch an und bestrafe euch noch siebenmal härter für eure Sünden." },
      { number: 29, text: "Dann werdet ihr das Fleisch eurer eigenen Söhne und Töchter essen." },
      { number: 30, text: "Ich werde eure Höhenheiligtümer zerstören und die Räucheraltäre zerschlagen. Ich werde euch verabscheuen und eure Leichen auf die Trümmer eurer Mistgötzen werfen." },
      { number: 31, text: "Eure Städte werde ich in Schutt und Asche legen und eure Heiligtümer öde machen. Den befriedigenden Geruch eurer Opfer will ich dann nicht mehr riechen." },
      { number: 32, text: "Ich werde das Land so verwüsten, dass sich selbst eure Feinde, die sich darin niederlassen, darüber entsetzen." },
      { number: 33, text: "Euch werde ich unter die Völker zerstreuen. Mit gezücktem Schwert bin ich hinter euch her. Euer Land wird veröden und eure Städte werden Trümmerhaufen sein." },
      { number: 34, text: "Dann, wenn das Land verödet daliegt, holt es seine Sabbatjahre nach. Während ihr im Land eurer Feinde leben müsst, wird das Land endlich ruhen und seine Sabbate ersetzt bekommen." },
      { number: 35, text: "Während der ganzen Zeit, in der es öde daliegt, wird es ruhen, wie es an den Sabbaten nicht ruhen konnte, als ihr darin wohntet." },
      { number: 36, text: "Und die von euch, die das überleben, werde ich im Land ihrer Feinde so schreckhaft machen, dass sie von einem raschelnden Blatt aufgescheucht werden. Sie werden fliehen, wie man vor dem Schwert flieht, und fallen, obwohl sie niemand verfolgt." },
      { number: 37, text: "Einer wird über den anderen stürzen wie auf der Flucht vor dem Schwert, obwohl sie niemand verfolgt. Ihr könnt vor euren Feinden nicht bestehen" },
      { number: 38, text: "und werdet in der Fremde zugrunde gehen. Das Land eurer Feinde wird euch fressen." },
      { number: 39, text: "Die Restlichen von euch werden im Land eurer Feinde verfaulen wegen ihrer Schuld, dahinsiechen wegen der Schuld ihrer Väter." },
      { number: 40, text: "Dann werden sie ihre Schuld und die Schuld ihrer Väter bekennen, dass sie mir die Treue gebrochen und sich mir widersetzt haben." },
      { number: 41, text: "Doch ich werde mich ihnen widersetzen und sie in das Land ihrer Feinde bringen, bis sich ihr trotziges Herz endlich beugt und sie ihre Schuld bezahlen." },
      { number: 42, text: "Dann werde ich an meinen Bund mit Jakob denken, mich erinnern an meinen Bund mit Isaak und Abraham, und dann denke ich auch an das Land." },
      { number: 43, text: "Das Land aber muss zunächst von ihnen verlassen werden, damit es seine Sabbatjahre nachholt, wenn es verödet daliegt ohne sie. Und sie müssen ihre Schuld bezahlen, weil sie meine Vorschriften missachtet und meine Ordnungen verabscheut haben." },
      { number: 44, text: "Doch selbst, wenn sie dann im Land ihrer Feinde sind, verwerfe ich sie nicht und hege keinen Widerwillen gegen sie. Ich gebe sie nicht dem Untergang preis, denn sonst müsste ich meinen Bund mit ihnen brechen. Ich bin doch Jahwe, ihr Gott!" },
      { number: 45, text: "Nein, um ihretwillen denke ich an meinen Bund mit ihren Vorfahren, die ich vor den Augen der Völker aus Ägypten herausgeführt habe, um ihr Gott zu sein. Ich bin Jahwe!\"" },
      { number: 46, text: "Das sind die Rechtsordnungen, Gebote und Gesetze, die Jahwe auf dem Berg Sinai zwischen sich und dem Volk Israel durch Mose erlassen hat." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Auslösung von Gelübden und Weihgaben" },
      { number: 2, text: "\"Gib den Israeliten Folgendes weiter: Wenn jemand gelobt, Jahwe einen Menschen zu weihen, ihn dann aber wieder auslösen will," },
      { number: 3, text: "beträgt der Wert eines zwanzig- bis sechzigjährigen Mannes fünfzig Silberstücke, wie es dem Gewicht des Heiligtums entspricht." },
      { number: 4, text: "Der Richtwert für eine Frau beträgt dreißig Silberstücke." },
      { number: 5, text: "Wenn die Person zwischen fünf und zwanzig Jahre alt ist, beträgt der Richtwert für die männliche Person zwanzig Silberstücke, für die weibliche zehn." },
      { number: 6, text: "Im Alter von einem Monat bis zu fünf Jahren ist der Richtwert für einen Knaben fünf Silberstücke, für ein Mädchen drei." },
      { number: 7, text: "Für Personen von sechzig Jahren und darüber beträgt der Richtwert für einen Mann fünfzehn Silberstücke, für eine Frau zehn." },
      { number: 8, text: "Wenn jemand zu arm ist, um den Richtwert zu zahlen, soll er die Person vor den Priester treten lassen, und der Priester soll sie nach dem Vermögen dessen einschätzen, der das Gelübde abgelegt hat." },
      { number: 9, text: "Wenn es sich um ein Stück Vieh handelt, das man Jahwe opfern darf, dann soll alles, was man Jahwe davon gibt, heilig sein." },
      { number: 10, text: "Man soll es nicht auswechseln und austauschen, ein gutes Tier nicht gegen ein schlechtes und ein schlechtes nicht gegen ein gutes. Wenn man es dennoch tut, soll das eine wie das andere Tier Jahwe geweiht sein." },
      { number: 11, text: "Handelt es sich um ein unreines Tier, das man Jahwe nicht opfern darf, dann soll man es vor den Priester stellen." },
      { number: 12, text: "Der Priester soll es nach seinen Vorzügen und Mängeln einschätzen, und bei seiner Schätzung soll es bleiben." },
      { number: 13, text: "Wenn der Besitzer das Tier zurückhaben will, muss er ein Fünftel zum Schätzwert dazuzahlen." },
      { number: 14, text: "Wenn jemand Jahwe sein Haus als heilige Gabe weiht, dann soll der Priester es nach seinen Vorzügen und Mängeln einschätzen, und bei seiner Schätzung soll es bleiben." },
      { number: 15, text: "Wenn der Betreffende das Haus zurückkaufen will, muss er ein Fünftel zum Schätzwert dazuzahlen, dann gehört es wieder ihm." },
      { number: 16, text: "Wenn jemand einen Teil seines Feldbesitzes Jahwe weiht, soll sich der Wert nach der Aussaat richten: Fünfzig Silberstücke für 165 Kilogramm Gerste*.", footnotes: ["Kilogramm Gerste. Hebräisch: ein Homer = 10 Efa = 220 Liter = 165 Kilogramm Gerstenkörner."] },
      { number: 17, text: "Weiht er sein Feld vom Jubeljahr an, soll dieser Schätzwert gelten." },
      { number: 18, text: "Weiht er es nach dem Jubeljahr, soll der Priester ihm den Preis nach den Jahren berechnen, die bis zum nächsten Jubeljahr bleiben und die Summe ermäßigen." },
      { number: 19, text: "Wenn der Betreffende das Feldstück unbedingt wieder zurückkaufen will, muss er ein Fünftel zum Schätzwert dazuzahlen, dann gehört es wieder ihm." },
      { number: 20, text: "Wenn er das Feldstück aber nicht wieder einlöst und es einem anderen verkauft wird, kann es nicht mehr zurückgekauft werden." },
      { number: 21, text: "Wird es dann im Jubeljahr frei, ist es wie ein Feld unter Bann für immer Jahwe geweiht. Es geht in den Besitz des Priesters über." },
      { number: 22, text: "Wenn jemand Jahwe ein gekauftes Feldstück weiht, das nicht zu seinem Erbbesitz gehört," },
      { number: 23, text: "soll ihm der Priester die Höhe des Schätzwertes bis zum Jubeljahr berechnen. Der Betrag gehört Jahwe und muss noch am gleichen Tag bezahlt werden." },
      { number: 24, text: "Im Jubeljahr fällt das Feldstück an den zurück, von dem es der Betreffende gekauft hat." },
      { number: 25, text: "Allen Schätzwerten sollst du das Gewicht des Heiligtums zugrunde legen, ein Silberstück zu zwölf Gramm*.", footnotes: ["zwölf Gramm. Wörtlich: ein Schekel zu zwanzig Gera. Das Gewicht eines Schekels betrug nach archäologischen Funden durchschnittlich etwa 11,5 Gramm, ein Gera demnach rund 0,6 Gramm."] },
      { number: 26, text: "Eine Erstgeburt von den Rindern, Schafen oder Ziegen gehört als Erstlingsgabe sowieso Jahwe und darf ihm nicht noch einmal geweiht werden." },
      { number: 27, text: "Handelt es sich aber um unreines Vieh, soll man es nach dem Schätzwert auslösen und noch ein Fünftel hinzufügen. Wird es nicht ausgelöst, soll es nach dem Schätzwert verkauft werden." },
      { number: 28, text: "Doch alles mit einem Bann belegte Gut, das jemand Jahwe weiht, sei es ein Mensch, ein Tier oder ein Stück Land, darf nicht ausgelöst oder verkauft werden. Es ist höchst heilig und gehört Jahwe." },
      { number: 29, text: "Kein Mensch, der mit dem Bann belegt wird, darf ausgelöst werden. Man muss ihn töten." },
      { number: 30, text: "Der zehnte Teil von jeder Ernte, auch von den Baumfrüchten, ist Jahwe geweiht und gehört ihm." },
      { number: 31, text: "Will jemand etwas von seinem Zehnten zurückkaufen, muss er zum Gegenwert noch ein Fünftel hinzuzahlen." },
      { number: 32, text: "Jedes zehnte Tier von Rindern, Schafen oder Ziegen, das unter dem Hirtenstab hindurchgeht, soll Jahwe geweiht sein." },
      { number: 33, text: "Man soll nicht untersuchen, ob es gut oder schlecht ist, und darf es nicht austauschen. Tauscht man dennoch eins aus, sind beide Tiere Jahwe geweiht und können nicht mehr ausgelöst werden.\"" },
      { number: 34, text: "Das sind die Gebote, die Jahwe Mose für die Israeliten auf dem Berg Sinai gegeben hat." },
    ] },
  ],
};